// ---- Shared setups: the layer an imported setup sits in -------------------------------------
// Every setting is read through here. An imported setup's values (the mod value "sharedSetup", as
// key=value lines) come first, then the settings page; quick settings still go on top of both.
// Reset Quick Settings clears it, and the settings page's values come back.
std::map<std::wstring, std::wstring> g_setupLayer;
bool g_setupLayerLoaded = false;

void VizSetupLoad() {
    g_setupLayerLoaded = true;
    g_setupLayer.clear();
    std::vector<WCHAR> buf(32768);
    if (!Wh_GetStringValue(L"sharedSetup", buf.data(), buf.size())) return;
    std::wstring s = buf.data();
    for (size_t pos = 0; pos < s.size();) {
        size_t nl = s.find(L'\n', pos);
        if (nl == std::wstring::npos) nl = s.size();
        std::wstring line = s.substr(pos, nl - pos);
        size_t eq = line.find(L'=');
        if (eq != std::wstring::npos && eq > 0) g_setupLayer[line.substr(0, eq)] = line.substr(eq + 1);
        pos = nl + 1;
    }
}

void VizSetupSave() {
    std::wstring s;
    for (const auto& kv : g_setupLayer) s += kv.first + L"=" + kv.second + L"\n";
    Wh_SetStringValue(L"sharedSetup", s.c_str());
}

// What the quick-settings panel is changing right now (a slider mid-drag), and what it has just
// written but the settings haven't caught up with yet. Read first of all. UI thread only.
struct VizPanelPending {
    std::wstring value;
    bool written = false;
};
std::map<std::wstring, VizPanelPending> g_panelPending;
std::atomic<bool> g_settingsFromHost{false};

const std::wstring* VizSetupFind(PCWSTR name) {
    if (!g_panelPending.empty()) {
        auto p = g_panelPending.find(name);
        if (p != g_panelPending.end()) return &p->second.value;
    }
    if (!g_setupLayerLoaded) VizSetupLoad();
    auto it = g_setupLayer.find(name);
    return it == g_setupLayer.end() ? nullptr : &it->second;
}

int VizSettingInt(PCWSTR name) {
    if (const std::wstring* v = VizSetupFind(name)) return *v == L"true" ? 1 : *v == L"false" ? 0 : _wtoi(v->c_str());
    return Wh_GetIntSetting(name);
}

PCWSTR VizSettingString(PCWSTR name) {
    std::wstring v;
    if (const std::wstring* found = VizSetupFind(name)) {
        v = *found;
    } else {
        PCWSTR s = Wh_GetStringSetting(name);
        v = s;
        Wh_FreeStringSetting(s);
    }
    WCHAR* out = new WCHAR[v.size() + 1];
    wcscpy_s(out, v.size() + 1, v.c_str());
    return out;
}

void VizSettingFree(PCWSTR s) { delete[] s; }

#ifndef TD_PREFIX
// The settings page's Outputs and Inputs (Windhawk): every device listed is heard, the first as the source and the
// rest mixed in, as the right-click menu's ticks. An entry is default_output, default_input, a device's id, or none.
std::vector<std::wstring> VizPageAudioList(PCWSTR key) {
    std::vector<std::wstring> out;
    for (int i = 0; i < 32; i++) {
        PCWSTR v = Wh_GetStringSetting(L"%s[%d]", key, i);
        std::wstring e = v ? v : L"";
        Wh_FreeStringSetting(v);
        while (!e.empty() && iswspace(e.back())) e.pop_back();
        while (!e.empty() && iswspace(e.front())) e.erase(e.begin());
        if (!e.empty() && e != L"none" && std::find(out.begin(), out.end(), e) == out.end()) out.push_back(e);
    }
    return out;
}
std::wstring g_pageAudioExtras;     // (the page's lists past the first: mixed in unless the menu's ticks stand over them)
bool g_pageAudioExtraLive = true;   // (audio.extraLive)
#endif

