// ---- track timeline: begin
// Track timeline from the media session, for the progress bar: start, end and
// position in 100 ns units, and the tick at which the position was current.
// Between updates the bar extrapolates while playing, since most players only
// report the position on a seek or a state change.
//
// Writers are WinRT thread-pool callbacks (two can run at once), serialised by
// g_tlWriteMutex; each write is tagged with the session generation it was read
// for, so a late event from a session that has since been replaced is dropped.
// The render thread reads without locking, through the g_tlSeq sequence count
// (odd while a write is in progress), so it never sees a position paired with
// another update's tick.
std::atomic<bool> g_tlValid{false};
std::atomic<int64_t> g_tlStart{0}, g_tlEnd{0}, g_tlPos{0};
std::atomic<ULONGLONG> g_tlTick{0};
std::atomic<bool> g_tlRunning{false};  // extrapolating: the session reported Playing
std::atomic<uint32_t> g_tlSeq{0};
std::atomic<uint32_t> g_tlGen{0};
std::mutex g_tlWriteMutex;

static void VizTlWriteBegin() {
    g_tlSeq.store(g_tlSeq.load(std::memory_order_relaxed) + 1, std::memory_order_relaxed);
    std::atomic_thread_fence(std::memory_order_release);
}
static void VizTlWriteEnd() {
    g_tlSeq.store(g_tlSeq.load(std::memory_order_relaxed) + 1, std::memory_order_release);
}

// A new media session is being hooked up: forget the old timeline and return
// the generation the new session's events must carry.
uint32_t VizTimelineNewSource() {
    std::lock_guard<std::mutex> lock(g_tlWriteMutex);
    uint32_t gen = g_tlGen.load(std::memory_order_relaxed) + 1;
    VizTlWriteBegin();
    g_tlGen.store(gen, std::memory_order_relaxed);
    g_tlValid.store(false, std::memory_order_relaxed);
    g_tlRunning.store(false, std::memory_order_relaxed);
    g_tlPos.store(0, std::memory_order_relaxed);
    g_tlTick.store(GetTickCount64(), std::memory_order_relaxed);
    VizTlWriteEnd();
    return gen;
}

// Playback status. On a Playing <-> Paused change the position so far is
// folded in and the clock restarts from now, so the bar neither jumps back
// when pausing nor forward by the length of the pause when resuming (players
// often leave the timeline itself untouched across a pause).
void VizTimelineSetPlaying(uint32_t gen, bool playing) {
    std::lock_guard<std::mutex> lock(g_tlWriteMutex);
    if (gen != g_tlGen.load(std::memory_order_relaxed)) return;
    g_mediaIsPlaying.store(playing, std::memory_order_relaxed);
    bool running = g_tlRunning.load(std::memory_order_relaxed);
    if (running == playing) return;
    ULONGLONG now = GetTickCount64();
    int64_t pos = g_tlPos.load(std::memory_order_relaxed);
    if (running) pos += (int64_t)(now - g_tlTick.load(std::memory_order_relaxed)) * 10000;
    VizTlWriteBegin();
    g_tlPos.store(pos, std::memory_order_relaxed);
    g_tlTick.store(now, std::memory_order_relaxed);
    g_tlRunning.store(playing, std::memory_order_relaxed);
    VizTlWriteEnd();
}

// A fresh timeline (TimelinePropertiesChanged, or the first read of a
// session). ageMs is how old the position already is (from LastUpdatedTime);
// it only counts while playing, since a paused position doesn't move.
void VizTimelineSet(uint32_t gen, int64_t start, int64_t end, int64_t pos, int64_t ageMs) {
    std::lock_guard<std::mutex> lock(g_tlWriteMutex);
    if (gen != g_tlGen.load(std::memory_order_relaxed)) return;
    if (ageMs < 0 || ageMs > 6LL * 3600 * 1000) ageMs = 0;  // unset or nonsense
    if (!g_tlRunning.load(std::memory_order_relaxed)) ageMs = 0;
    VizTlWriteBegin();
    g_tlStart.store(start, std::memory_order_relaxed);
    g_tlEnd.store(end, std::memory_order_relaxed);
    g_tlPos.store(pos, std::memory_order_relaxed);
    g_tlTick.store(GetTickCount64() - (ULONGLONG)ageMs, std::memory_order_relaxed);
    g_tlValid.store(end > start, std::memory_order_relaxed);
    VizTlWriteEnd();
}

void VizTimelineInvalidate(uint32_t gen) {
    std::lock_guard<std::mutex> lock(g_tlWriteMutex);
    if (gen != g_tlGen.load(std::memory_order_relaxed)) return;
    VizTlWriteBegin();
    g_tlValid.store(false, std::memory_order_relaxed);
    VizTlWriteEnd();
}

// 0..1 along the track, or -1 for no bar. Render thread.
float VizTrackProgress() {
    static std::atomic<float> s_last{-1.f};  // if a writer is preempted mid-update
    bool valid = false, running = false;
    int64_t start = 0, end = 0, pos = 0;
    ULONGLONG tick = 0;
    for (int tries = 0;; tries++) {
        if (tries == 64) return s_last.load(std::memory_order_relaxed);
        uint32_t s1 = g_tlSeq.load(std::memory_order_acquire);
        if (s1 & 1u) continue;
        valid = g_tlValid.load(std::memory_order_relaxed);
        start = g_tlStart.load(std::memory_order_relaxed);
        end = g_tlEnd.load(std::memory_order_relaxed);
        pos = g_tlPos.load(std::memory_order_relaxed);
        tick = g_tlTick.load(std::memory_order_relaxed);
        running = g_tlRunning.load(std::memory_order_relaxed);
        std::atomic_thread_fence(std::memory_order_acquire);
        if (g_tlSeq.load(std::memory_order_relaxed) == s1) break;
    }
    float result = -1.f;
    double dur = (double)(end - start);
    if (valid && dur > 0.0) {
        double p = (double)(pos - start);
        if (running) {
            // Modular difference, so a tick set back past boot by an age still works.
            int64_t elapsedMs = (int64_t)(GetTickCount64() - tick);
            if (elapsedMs > 0) p += (double)elapsedMs * 10000.0;
        }
        result = (float)std::clamp(p / dur, 0.0, 1.0);
    }
    s_last.store(result, std::memory_order_relaxed);
    return result;
}

// ---- Lyrics, part 1: finding them and timing them -----------------------------------------------------------------
// Off unless Lyrics is on. On a new track a worker looks, in order: the cache (%LOCALAPPDATA%\Tourne\Lyrics), your
// folder ("Artist - Title.lrc" or "Title.lrc"), and only with Look Up Online on, lrclib.net, which is sent the song's
// artist, title and album and nothing else, as "TourneTable". What it finds goes in the cache, so a song is asked
// for once (and "not found" is remembered for a week). Lines are timed from the media session's position, plus the
// offset; word-timed (enhanced) LRC files give each word its own time.
struct VizLyricLine {
    int64_t ms = 0;                                  // when the line starts
    std::wstring text;
    std::vector<std::pair<int64_t, int>> words;      // (start ms, first character) for word-timed files
};
struct VizLyricSet {
    std::wstring key;                                // "artist\ntitle", lower case
    std::vector<VizLyricLine> lines;                 // in time order
    bool synced = false;                             // false: plain text, untimed
    std::wstring from;                               // cache, folder, online
    std::vector<std::wstring> trans;                 // Translate Lyrics: each line's translation ("" none), or empty
    std::wstring transFrom;                          // where it's from (your file, NetEase, Genius)
};
std::mutex g_lyricsMutex;
std::shared_ptr<const VizLyricSet> g_lyrics;         // the playing song's, or null
std::atomic<uint32_t> g_lyricsSerial{0};             // one more each time g_lyrics changes
std::wstring g_lyricsWantArtist, g_lyricsWantTitle, g_lyricsWantAlbum;  // (under g_lyricsMutex)
HANDLE g_lyricsWake = nullptr;
std::thread* g_lyricsThread = nullptr;
std::atomic<bool> g_lyricsStop{false};
std::atomic<bool> g_lyricsTransAgain{false};         // Translate Lyrics' settings changed: the song looked at again

std::wstring VizLyricsLower(std::wstring s) {
    for (auto& c : s) c = (wchar_t)towlower(c);
    return s;
}

// [mm:ss.xx] (or [m:ss], [mm:ss:xx]) at s, its time in ms; false if s isn't one. n: its length.
bool VizLrcTime(const std::wstring& s, size_t at, wchar_t open, wchar_t close, int64_t* ms, size_t* n) {
    if (at >= s.size() || s[at] != open) return false;
    size_t end = s.find(close, at + 1);
    if (end == std::wstring::npos || end - at > 16) return false;
    std::wstring in = s.substr(at + 1, end - at - 1);
    int mm = 0, ss = 0, frac = 0, fracDigits = 0;
    size_t i = 0;
    auto digits = [&](int& v) {
        size_t start = i;
        while (i < in.size() && iswdigit(in[i])) v = v * 10 + (in[i++] - L'0');
        return i > start;
    };
    if (!digits(mm) || i >= in.size() || in[i] != L':') return false;
    i++;
    if (!digits(ss)) return false;
    if (i < in.size() && (in[i] == L'.' || in[i] == L':')) {
        i++;
        size_t start = i;
        while (i < in.size() && iswdigit(in[i]) && fracDigits < 3) frac = frac * 10 + (in[i++] - L'0'), fracDigits++;
        while (i < in.size() && iswdigit(in[i])) i++;
        if (i == start) return false;
    }
    if (i != in.size()) return false;
    while (fracDigits < 3) frac *= 10, fracDigits++;
    *ms = (int64_t)mm * 60000 + (int64_t)ss * 1000 + frac;
    *n = end - at + 1;
    return true;
}

// An LRC file (or plain lyrics) as lines. Plain text with no time tags comes back untimed.
VizLyricSet VizParseLrc(const std::wstring& text) {
    VizLyricSet set;
    int64_t offset = 0;
    std::vector<std::wstring> plain;
    size_t at = 0;
    while (at <= text.size()) {
        size_t nl = text.find(L'\n', at);
        std::wstring line = text.substr(at, nl == std::wstring::npos ? std::wstring::npos : nl - at);
        at = nl == std::wstring::npos ? text.size() + 1 : nl + 1;
        while (!line.empty() && (line.back() == L'\r' || line.back() == L' ')) line.pop_back();
        if (line.empty()) continue;
        // [offset:+250] and the other tags
        if (line[0] == L'[' && line.size() > 3 && iswalpha(line[1])) {
            size_t colon = line.find(L':'), close = line.find(L']');
            if (colon != std::wstring::npos && close != std::wstring::npos && colon < close) {
                if (VizLyricsLower(line.substr(1, colon - 1)) == L"offset") offset = _wtoi64(line.substr(colon + 1, close - colon - 1).c_str());
                continue;
            }
        }
        std::vector<int64_t> times;
        size_t p = 0, n = 0;
        int64_t ms = 0;
        while (VizLrcTime(line, p, L'[', L']', &ms, &n)) times.push_back(ms), p += n;
        if (times.empty()) {
            plain.push_back(line);
            continue;
        }
        // The rest: words, maybe each with <mm:ss.xx> before it.
        VizLyricLine l;
        std::wstring rest = line.substr(p);
        for (size_t i = 0; i < rest.size();) {
            if (VizLrcTime(rest, i, L'<', L'>', &ms, &n)) {
                l.words.push_back({ms - offset, (int)l.text.size()});
                i += n;
                continue;
            }
            l.text += rest[i++];
        }
        while (!l.text.empty() && l.text.front() == L' ') {
            l.text.erase(l.text.begin());
            for (auto& w : l.words) w.second = std::max(0, w.second - 1);
        }
        for (int64_t t : times) {
            VizLyricLine copy = l;
            copy.ms = t - offset;
            for (auto& w : copy.words) w.first += t - times[0];  // (a repeated line: its words move with it)
            set.lines.push_back(copy);
        }
    }
    if (!set.lines.empty()) {
        std::stable_sort(set.lines.begin(), set.lines.end(), [](auto const& a, auto const& b) { return a.ms < b.ms; });
        set.synced = true;
    } else {
        for (auto& t : plain) {
            VizLyricLine l;
            l.text = t;
            set.lines.push_back(l);
        }
    }
    return set;
}

std::wstring VizLyricsFileName(std::wstring s) {
    for (auto& c : s)
        if (wcschr(L"<>:\"/\\|?*", c) || c < 32) c = L'_';
    while (!s.empty() && (s.back() == L'.' || s.back() == L' ')) s.pop_back();
    if (s.size() > 150) s.resize(150);
    return s;
}

std::wstring VizLyricsCacheDir() {
    WCHAR base[MAX_PATH];
    DWORD n = GetEnvironmentVariableW(L"LOCALAPPDATA", base, MAX_PATH);
    if (!n || n >= MAX_PATH) return L"";
    std::wstring dir = std::wstring(base) + L"\\Tourne";
    CreateDirectoryW(dir.c_str(), nullptr);
    dir += L"\\Lyrics";
    CreateDirectoryW(dir.c_str(), nullptr);
    return dir;
}

bool VizReadTextFile(const std::wstring& path, std::wstring* out, int64_t most = 2 * 1024 * 1024) {  // (most: lyrics files are small)
    HANDLE f = CreateFileW(path.c_str(), GENERIC_READ, FILE_SHARE_READ, nullptr, OPEN_EXISTING, 0, nullptr);
    if (f == INVALID_HANDLE_VALUE) return false;
    LARGE_INTEGER size{};
    GetFileSizeEx(f, &size);
    if (size.QuadPart > most) {
        CloseHandle(f);
        return false;
    }
    std::string bytes((size_t)size.QuadPart, '\0');
    DWORD got = 0;
    BOOL ok = bytes.empty() || ReadFile(f, bytes.data(), (DWORD)bytes.size(), &got, nullptr);
    CloseHandle(f);
    if (!ok) return false;
    bytes.resize(got);
    if (bytes.size() >= 2 && (unsigned char)bytes[0] == 0xFF && (unsigned char)bytes[1] == 0xFE) {  // UTF-16
        out->assign((const wchar_t*)(bytes.data() + 2), (bytes.size() - 2) / 2);
        return true;
    }
    if (bytes.size() >= 3 && (unsigned char)bytes[0] == 0xEF && (unsigned char)bytes[1] == 0xBB) bytes.erase(0, 3);
    int wn = MultiByteToWideChar(CP_UTF8, 0, bytes.data(), (int)bytes.size(), nullptr, 0);
    out->assign(wn, L'\0');
    MultiByteToWideChar(CP_UTF8, 0, bytes.data(), (int)bytes.size(), out->data(), wn);
    return true;
}

void VizWriteTextFile(const std::wstring& path, const std::wstring& text) {
    int n = WideCharToMultiByte(CP_UTF8, 0, text.c_str(), (int)text.size(), nullptr, 0, nullptr, nullptr);
    std::string bytes(n, '\0');
    WideCharToMultiByte(CP_UTF8, 0, text.c_str(), (int)text.size(), bytes.data(), n, nullptr, nullptr);
    HANDLE f = CreateFileW(path.c_str(), GENERIC_WRITE, 0, nullptr, CREATE_ALWAYS, 0, nullptr);
    if (f == INVALID_HANDLE_VALUE) return;
    DWORD put = 0;
    WriteFile(f, bytes.data(), (DWORD)bytes.size(), &put, nullptr);
    CloseHandle(f);
}

std::string VizUrlPart(const std::wstring& s) {
    int n = WideCharToMultiByte(CP_UTF8, 0, s.c_str(), (int)s.size(), nullptr, 0, nullptr, nullptr);
    std::string u(n, '\0');
    WideCharToMultiByte(CP_UTF8, 0, s.c_str(), (int)s.size(), u.data(), n, nullptr, nullptr);
    std::string out;
    for (unsigned char c : u) {
        if (isalnum(c) || c == '-' || c == '_' || c == '.' || c == '~') out += (char)c;
        else {
            char hex[4];
            snprintf(hex, sizeof(hex), "%%%02X", c);
            out += hex;
        }
    }
    return out;
}

// The JSON string value after "key": at from, unescaped; npos-safe. Returns the position after it, or npos.
size_t VizJsonString(const std::string& j, const char* key, size_t from, std::wstring* out) {
    std::string k = std::string("\"") + key + "\"";
    size_t at = j.find(k, from);
    if (at == std::string::npos) return std::string::npos;
    at = j.find(':', at + k.size());
    if (at == std::string::npos) return std::string::npos;
    at = j.find_first_not_of(" \t\r\n", at + 1);
    if (at == std::string::npos) return std::string::npos;
    if (j.compare(at, 4, "null") == 0) {
        out->clear();
        return at + 4;
    }
    if (j[at] != '"') return std::string::npos;
    std::string s;
    size_t i = at + 1;
    for (; i < j.size() && j[i] != '"'; i++) {
        if (j[i] != '\\' || i + 1 >= j.size()) {
            s += j[i];
            continue;
        }
        char e = j[++i];
        if (e == 'n') s += '\n';
        else if (e == 't') s += '\t';
        else if (e == 'r') s += '\r';
        else if (e == 'u' && i + 4 < j.size()) {
            unsigned cp = (unsigned)strtoul(j.substr(i + 1, 4).c_str(), nullptr, 16);
            i += 4;
            if (cp >= 0xD800 && cp <= 0xDBFF && i + 6 < j.size() && j[i + 1] == '\\' && j[i + 2] == 'u') {
                unsigned lo = (unsigned)strtoul(j.substr(i + 3, 4).c_str(), nullptr, 16);
                cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                i += 6;
            }
            if (cp < 0x80) s += (char)cp;
            else if (cp < 0x800) s += (char)(0xC0 | (cp >> 6)), s += (char)(0x80 | (cp & 63));
            else if (cp < 0x10000) s += (char)(0xE0 | (cp >> 12)), s += (char)(0x80 | ((cp >> 6) & 63)), s += (char)(0x80 | (cp & 63));
            else s += (char)(0xF0 | (cp >> 18)), s += (char)(0x80 | ((cp >> 12) & 63)), s += (char)(0x80 | ((cp >> 6) & 63)), s += (char)(0x80 | (cp & 63));
        } else s += e;
    }
    int wn = MultiByteToWideChar(CP_UTF8, 0, s.data(), (int)s.size(), nullptr, 0);
    out->assign(wn, L'\0');
    MultiByteToWideChar(CP_UTF8, 0, s.data(), (int)s.size(), out->data(), wn);
    return i + 1;
}

// One GET, nothing kept (no cookies, no cache of WinINet's own), at most 4 MB; "" on any failure. The answer is data.
std::string VizHttpGet(const std::wstring& url, const wchar_t* headers, DWORD* statusOut = nullptr) {
    std::string body;
    if (statusOut) *statusOut = 0;
    if (HINTERNET net = InternetOpenW(L"TourneTable", INTERNET_OPEN_TYPE_PRECONFIG, nullptr, nullptr, 0)) {
        DWORD timeout = 8000;
        InternetSetOptionW(net, INTERNET_OPTION_CONNECT_TIMEOUT, &timeout, sizeof(timeout));
        InternetSetOptionW(net, INTERNET_OPTION_RECEIVE_TIMEOUT, &timeout, sizeof(timeout));
        DWORD flags = INTERNET_FLAG_NO_COOKIES | INTERNET_FLAG_NO_CACHE_WRITE | INTERNET_FLAG_RELOAD | INTERNET_FLAG_NO_UI | INTERNET_FLAG_NO_AUTH;
        if (url.rfind(L"https:", 0) == 0) flags |= INTERNET_FLAG_SECURE;
        if (HINTERNET r = InternetOpenUrlW(net, url.c_str(), headers, headers ? (DWORD)-1 : 0, flags, 0)) {
            DWORD status = 0, sz = sizeof(status);
            HttpQueryInfoW(r, HTTP_QUERY_STATUS_CODE | HTTP_QUERY_FLAG_NUMBER, &status, &sz, nullptr);
            if (statusOut) *statusOut = status;
            char buf[16384];
            DWORD got = 0;
            while (status == 200 && InternetReadFile(r, buf, sizeof(buf), &got) && got && body.size() < 4 * 1024 * 1024) body.append(buf, got);
            InternetCloseHandle(r);
        }
        InternetCloseHandle(net);
    }
    return body;
}

// Lower case letters and digits only, for comparing names from different places.
std::wstring VizLyricsKeyOf(const std::wstring& s) {
    std::wstring o;
    for (wchar_t c : s)
        if (iswalnum(c)) o += towlower(c);
    return o;
}
bool VizLyricsNameLike(const std::wstring& a, const std::wstring& b) {
    const std::wstring x = VizLyricsKeyOf(a), y = VizLyricsKeyOf(b);
    return !x.empty() && !y.empty() && (x.find(y) != std::wstring::npos || y.find(x) != std::wstring::npos);
}

// Text from a page or a site: tags out (a <br> is a line), entities in, nothing else kept. UTF-8 in.
std::wstring VizLyricsPlainText(const std::string& in) {
    std::string t;
    for (size_t i = 0; i < in.size(); i++) {
        if (in[i] == '<') {
            size_t e = in.find('>', i);
            if (e == std::string::npos) break;
            std::string tag = in.substr(i + 1, std::min<size_t>(e - i - 1, 8));
            for (auto& c : tag) c = (char)tolower((unsigned char)c);
            if (tag.rfind("br", 0) == 0 || tag.rfind("/p", 0) == 0 || tag.rfind("/div", 0) == 0) t += '\n';
            i = e;
            continue;
        }
        if (in[i] == '&') {
            size_t e = in.find(';', i);
            if (e != std::string::npos && e - i <= 8) {
                std::string ent = in.substr(i + 1, e - i - 1);
                unsigned cp = 0;
                if (ent == "amp") cp = '&';
                else if (ent == "lt") cp = '<';
                else if (ent == "gt") cp = '>';
                else if (ent == "quot") cp = '"';
                else if (ent == "apos") cp = '\'';
                else if (ent == "nbsp") cp = ' ';
                else if (ent.size() > 1 && ent[0] == '#') cp = (unsigned)strtoul(ent.c_str() + (ent[1] == 'x' ? 2 : 1), nullptr, ent[1] == 'x' ? 16 : 10);
                if (cp) {
                    if (cp < 0x80) t += (char)cp;
                    else if (cp < 0x800) t += (char)(0xC0 | (cp >> 6)), t += (char)(0x80 | (cp & 63));
                    else t += (char)(0xE0 | (cp >> 12)), t += (char)(0x80 | ((cp >> 6) & 63)), t += (char)(0x80 | (cp & 63));
                    i = e;
                    continue;
                }
            }
        }
        if ((unsigned char)in[i] < 32 && in[i] != '\n' && in[i] != '\t') continue;
        t += in[i];
    }
    int wn = MultiByteToWideChar(CP_UTF8, 0, t.data(), (int)t.size(), nullptr, 0);
    std::wstring w(wn, L'\0');
    MultiByteToWideChar(CP_UTF8, 0, t.data(), (int)t.size(), w.data(), wn);
    // Lines trimmed, no runs of blank lines.
    std::wstring out, line;
    int blanks = 0;
    for (size_t i = 0; i <= w.size(); i++) {
        if (i < w.size() && w[i] != L'\n') {
            line += w[i] == L'\t' ? L' ' : w[i];
            continue;
        }
        while (!line.empty() && line.back() == L' ') line.pop_back();
        while (!line.empty() && line.front() == L' ') line.erase(line.begin());
        if (line.empty()) blanks++;
        else {
            if (!out.empty()) out += blanks ? L"\n\n" : L"\n";
            out += line;
            blanks = 0;
        }
        line.clear();
    }
    return out;
}

std::wstring VizUtf8ToWide(const std::string& s) {
    int wn = MultiByteToWideChar(CP_UTF8, 0, s.data(), (int)s.size(), nullptr, 0);
    std::wstring w(wn, L'\0');
    MultiByteToWideChar(CP_UTF8, 0, s.data(), (int)s.size(), w.data(), wn);
    return w;
}

// lrclib.net, looser: the artist and title as one phrase; the result whose names are like the song's and whose length
// is closest (timed first).
std::wstring VizLyricsLrclibLoose(const std::wstring& artist, const std::wstring& title, int64_t durMs) {
    const std::string body = VizHttpGet(L"https://lrclib.net/api/search?q=" + VizUtf8ToWide(VizUrlPart(artist + L" " + title)), L"Accept: application/json");
    std::wstring best, plain;
    double bestGap = 1e18;
    for (size_t at = 0; (at = body.find("\"id\"", at)) != std::string::npos; at++) {
        size_t next = body.find("\"id\"", at + 4);
        std::string obj = body.substr(at, next == std::string::npos ? std::string::npos : next - at);
        std::wstring tn, an, synced, pl;
        VizJsonString(obj, "trackName", 0, &tn);
        VizJsonString(obj, "artistName", 0, &an);
        if (!VizLyricsNameLike(tn, title) || (!artist.empty() && !VizLyricsNameLike(an, artist))) continue;
        double dur = 0;
        if (size_t d = obj.find("\"duration\""); d != std::string::npos) dur = atof(obj.c_str() + obj.find(':', d) + 1);
        VizJsonString(obj, "syncedLyrics", 0, &synced);
        VizJsonString(obj, "plainLyrics", 0, &pl);
        const double gap = durMs > 0 ? fabs(dur * 1000.0 - (double)durMs) : 0.0;
        if (!synced.empty() && gap < bestGap) best = synced, bestGap = gap;
        if (plain.empty() && !pl.empty()) plain = pl;
    }
    if (!best.empty() && (durMs <= 0 || bestGap < 10000)) return best;
    return plain;
}

// The end of the JSON value (object or array) starting at `at` ('{' or '['), strings skipped; npos if it doesn't end.
size_t VizJsonEnd(const std::string& j, size_t at) {
    int depth = 0;
    for (size_t i = at; i < j.size(); i++) {
        const char c = j[i];
        if (c == '"') {
            for (i++; i < j.size() && j[i] != '"'; i++)
                if (j[i] == '\\') i++;
            continue;
        }
        if (c == '{' || c == '[') depth++;
        else if ((c == '}' || c == ']') && --depth == 0) return i + 1;
    }
    return std::string::npos;
}

// NetEase Cloud Music: its search (songs: their artists, then their own name and id, and length), then the timed
// lyrics of the song whose names are like this one's and whose length is closest.
std::string VizNeteaseFind(const std::wstring& artist, const std::wstring& title, int64_t durMs) {
    const std::string body = VizHttpGet(L"https://music.163.com/api/search/get?type=1&limit=10&s=" + VizUtf8ToWide(VizUrlPart(artist + L" " + title)),
                                        L"Referer: https://music.163.com\r\nAccept: application/json");
    std::string bestId;
    double bestGap = 1e18;
    for (size_t at = 0; (at = body.find("\"duration\":", at)) != std::string::npos; at++) {
        const double dur = atof(body.c_str() + at + 11);
        size_t arts = body.find("\"artists\":[", at);
        if (arts == std::string::npos) break;
        size_t artsEnd = VizJsonEnd(body, arts + 10);
        if (artsEnd == std::string::npos) break;
        const std::string artsJson = body.substr(arts, artsEnd - arts);
        bool artistOk = artist.empty();
        for (size_t p = 0;;) {
            std::wstring an;
            p = VizJsonString(artsJson, "name", p, &an);
            if (p == std::string::npos) break;
            if (VizLyricsNameLike(an, artist)) artistOk = true;
        }
        std::wstring name;
        size_t afterName = VizJsonString(body, "name", artsEnd, &name);
        if (afterName == std::string::npos) break;
        size_t idAt = body.find("\"id\":", afterName);
        if (idAt == std::string::npos || idAt - afterName > 64) continue;
        std::string id;
        for (size_t i = idAt + 5; i < body.size() && isdigit((unsigned char)body[i]); i++) id += body[i];
        if (id.empty() || !artistOk || !VizLyricsNameLike(name, title)) continue;
        const double gap = durMs > 0 ? fabs(dur - (double)durMs) : 0.0;
        if (gap < bestGap) bestGap = gap, bestId = id;
    }
    if (bestId.empty() || (durMs > 0 && bestGap > 10000)) return "";
    return bestId;
}
std::wstring VizLyricsNetease(const std::wstring& artist, const std::wstring& title, int64_t durMs) {
    const std::string bestId = VizNeteaseFind(artist, title, durMs);
    if (bestId.empty()) return L"";
    const std::string lyr = VizHttpGet(L"https://music.163.com/api/song/lyric?lv=1&id=" + VizUtf8ToWide(bestId), L"Referer: https://music.163.com\r\nAccept: application/json");
    size_t lrc = lyr.find("\"lrc\"");
    std::wstring text;
    if (lrc != std::string::npos) VizJsonString(lyr, "lyric", lrc, &text);
    return text.find(L'[') != std::wstring::npos ? text : L"";  // (timed only: NetEase's untimed answers are mostly notes)
}

std::wstring VizGeniusWords(const std::wstring& url);
// Genius: its search with the token, then the words read off the song's web page (genius.com only). Untimed.
std::wstring VizLyricsGenius(const std::wstring& artist, const std::wstring& title, const std::wstring& token) {
    const std::wstring auth = L"Authorization: Bearer " + token + L"\r\nAccept: application/json";
    const std::string body = VizHttpGet(L"https://api.genius.com/search?q=" + VizUtf8ToWide(VizUrlPart(artist + L" " + title)), auth.c_str());
    std::wstring url;
    for (size_t at = 0; (at = body.find("\"result\":", at)) != std::string::npos; at++) {
        size_t end = VizJsonEnd(body, body.find('{', at));
        if (end == std::string::npos) break;
        const std::string r = body.substr(at, end - at);
        std::wstring t, u, an;
        VizJsonString(r, "title", 0, &t);
        VizJsonString(r, "url", 0, &u);
        if (size_t pa = r.find("\"primary_artist\""); pa != std::string::npos) VizJsonString(r, "name", pa, &an);
        if (u.rfind(L"https://genius.com/", 0) == 0 && VizLyricsNameLike(t, title) && (artist.empty() || VizLyricsNameLike(an, artist))) {
            url = u;
            break;
        }
    }
    return VizGeniusWords(url);
}
std::wstring VizGeniusWords(const std::wstring& url) {
    if (url.rfind(L"https://genius.com/", 0) != 0) return L"";
    const std::string page = VizHttpGet(url, L"Accept: text/html");
    std::string words;
    for (size_t at = 0; (at = page.find("data-lyrics-container=\"true\"", at)) != std::string::npos;) {
        size_t open = page.find('>', at);
        if (open == std::string::npos) break;
        // To this div's own end (divs inside counted).
        int depth = 1;
        size_t i = open + 1;
        while (i < page.size() && depth > 0) {
            size_t nextOpen = page.find("<div", i), nextClose = page.find("</div", i);
            if (nextClose == std::string::npos) break;
            if (nextOpen != std::string::npos && nextOpen < nextClose) depth++, i = nextOpen + 4;
            else depth--, i = nextClose + 5;
        }
        words += page.substr(open + 1, (depth == 0 ? page.rfind("</div", i) : i) - open - 1) + "<br>";
        at = i;
    }
    return VizLyricsPlainText(words);
}

// Your own site: the address with the song filled in; .lrc or plain text back (markup stripped).
std::wstring VizLyricsMySite(const std::wstring& tmpl, const std::wstring& artist, const std::wstring& title, const std::wstring& album, int64_t durMs) {
    if (tmpl.rfind(L"http://", 0) != 0 && tmpl.rfind(L"https://", 0) != 0) return L"";
    std::wstring url = tmpl;
    auto fill = [&](const wchar_t* key, const std::wstring& v) {
        const std::wstring enc = VizUtf8ToWide(VizUrlPart(v));
        for (size_t p; (p = url.find(key)) != std::wstring::npos;) url.replace(p, wcslen(key), enc);
    };
    fill(L"{artist}", artist), fill(L"{title}", title), fill(L"{album}", album), fill(L"{length}", std::to_wstring(durMs / 1000));
    const std::string body = VizHttpGet(url, L"Accept: text/plain, */*");
    if (body.find('<') == std::string::npos) return VizUtf8ToWide(body);
    return VizLyricsPlainText(body);
}

// Last.fm's correction of an artist and title (your API key); leaves them as they are when it has none.
void VizLyricsLastfmFix(std::wstring* artist, std::wstring* title, const std::wstring& key) {
    const std::string body = VizHttpGet(L"https://ws.audioscrobbler.com/2.0/?method=track.getcorrection&format=json&api_key=" +
                                        VizUtf8ToWide(VizUrlPart(key)) + L"&artist=" + VizUtf8ToWide(VizUrlPart(*artist)) +
                                        L"&track=" + VizUtf8ToWide(VizUrlPart(*title)), L"Accept: application/json");
    size_t tr = body.find("\"track\"");
    if (tr == std::string::npos) return;
    std::wstring t, a;
    size_t after = VizJsonString(body, "name", tr, &t);
    if (after == std::string::npos) return;
    size_t ar = body.find("\"artist\"", after);
    if (ar != std::string::npos) VizJsonString(body, "name", ar, &a);
    if (!t.empty()) *title = t;
    if (!a.empty()) *artist = a;
}

// lrclib.net's search: the match closest in length (when known) with timed lyrics, else plain ones. "" if none.
std::wstring VizLyricsOnline(const std::wstring& artist, const std::wstring& title, const std::wstring& album, int64_t durMs,
                             bool* reached) {
    *reached = false;
    std::string path = "/api/search?track_name=" + VizUrlPart(title) + "&artist_name=" + VizUrlPart(artist);
    if (!album.empty()) path += "&album_name=" + VizUrlPart(album);
    std::string body;
    if (HINTERNET net = InternetOpenW(L"TourneTable", INTERNET_OPEN_TYPE_PRECONFIG, nullptr, nullptr, 0)) {
        DWORD timeout = 8000;
        InternetSetOptionW(net, INTERNET_OPTION_CONNECT_TIMEOUT, &timeout, sizeof(timeout));
        InternetSetOptionW(net, INTERNET_OPTION_RECEIVE_TIMEOUT, &timeout, sizeof(timeout));
        std::wstring url = L"https://lrclib.net" + std::wstring(path.begin(), path.end());
        // No cookies, no cache of its own, nothing kept by WinINet: the answer goes in our cache.
        const DWORD flags = INTERNET_FLAG_SECURE | INTERNET_FLAG_NO_COOKIES | INTERNET_FLAG_NO_CACHE_WRITE |
                            INTERNET_FLAG_RELOAD | INTERNET_FLAG_NO_UI | INTERNET_FLAG_NO_AUTH;
        if (HINTERNET r = InternetOpenUrlW(net, url.c_str(), L"Accept: application/json", (DWORD)-1, flags, 0)) {
            DWORD status = 0, sz = sizeof(status);
            HttpQueryInfoW(r, HTTP_QUERY_STATUS_CODE | HTTP_QUERY_FLAG_NUMBER, &status, &sz, nullptr);
            *reached = status == 200 || status == 404;
            char buf[16384];
            DWORD got = 0;
            while (status == 200 && InternetReadFile(r, buf, sizeof(buf), &got) && got && body.size() < 4 * 1024 * 1024)
                body.append(buf, got);
            InternetCloseHandle(r);
        }
        InternetCloseHandle(net);
    }
    // Each result: its "duration" (s) and "syncedLyrics" / "plainLyrics".
    std::wstring best, plain;
    double bestGap = 1e18;
    for (size_t at = 0; (at = body.find("\"id\"", at)) != std::string::npos; at++) {
        size_t next = body.find("\"id\"", at + 4);
        std::string obj = body.substr(at, next == std::string::npos ? std::string::npos : next - at);
        double dur = 0;
        if (size_t d = obj.find("\"duration\""); d != std::string::npos) dur = atof(obj.c_str() + obj.find(':', d) + 1);
        std::wstring synced, pl;
        VizJsonString(obj, "syncedLyrics", 0, &synced);
        VizJsonString(obj, "plainLyrics", 0, &pl);
        double gap = durMs > 0 ? fabs(dur * 1000.0 - (double)durMs) : 0.0;
        if (!synced.empty() && gap < bestGap) best = synced, bestGap = gap;
        if (plain.empty() && !pl.empty()) plain = pl;
    }
    if (!best.empty() && (durMs <= 0 || bestGap < 8000)) return best;
    return plain;
}

// ---- Translate Lyrics: people's translations, never a machine's ------------------------------------------------------
// The language: the setting's code, or Windows' display language's ("en" from en-GB).
std::wstring VizTransLanguage(const std::wstring& setting) {
    std::wstring code = setting;
    if (code.empty()) {
        wchar_t name[LOCALE_NAME_MAX_LENGTH] = L"";
        if (LCIDToLocaleName(MAKELCID(GetUserDefaultUILanguage(), SORT_DEFAULT), name, LOCALE_NAME_MAX_LENGTH, 0)) code = name;
    }
    if (size_t d = code.find_first_of(L"-_"); d != std::wstring::npos) code.resize(d);
    for (auto& c : code) c = (wchar_t)towlower(c);
    std::wstring ok;
    for (wchar_t c : code)
        if (c >= L'a' && c <= L'z') ok += c;
    return ok.size() >= 2 && ok.size() <= 3 ? ok : L"";
}
// A language's names as Genius writes them: in English, and in the language itself (its translators' pages).
struct VizTransLangName { const wchar_t* code; const wchar_t* english; const wchar_t* own; };
const VizTransLangName kVizTransLangs[] = {
    {L"en", L"English", L"English"},     {L"es", L"Spanish", L"Espa\u00f1ol"},   {L"fr", L"French", L"Fran\u00e7ais"},
    {L"de", L"German", L"Deutsch"},      {L"it", L"Italian", L"Italian"},        {L"pt", L"Portuguese", L"Portugu\u00eas"},
    {L"ru", L"Russian", L"\u0420\u0443\u0441\u0441\u043a"}, {L"ja", L"Japanese", L"\u65e5\u672c\u8a9e"}, {L"ko", L"Korean", L"\ud55c\uad6d\uc5b4"},
    {L"zh", L"Chinese", L"\u4e2d\u6587"}, {L"tr", L"Turkish", L"T\u00fcrk\u00e7e"}, {L"pl", L"Polish", L"Polsk"},
    {L"nl", L"Dutch", L"Nederlands"},    {L"sv", L"Swedish", L"Svensk"},          {L"uk", L"Ukrainian", L"\u0423\u043a\u0440\u0430\u0457\u043d"},
    {L"ar", L"Arabic", L"\u0627\u0644\u0639\u0631\u0628\u064a\u0629"}, {L"hi", L"Hindi", L"\u0939\u093f\u0928\u094d\u0926\u0940"},
    {L"id", L"Indonesian", L"Indonesia"}, {L"vi", L"Vietnamese", L"Vi\u1ec7t"},  {L"th", L"Thai", L"\u0e44\u0e17\u0e22"},
    {L"fa", L"Persian", L"\u0641\u0627\u0631\u0633\u06cc"}, {L"he", L"Hebrew", L"\u05e2\u05d1\u05e8\u05d9\u05ea"}, {L"el", L"Greek", L"\u0395\u03bb\u03bb\u03b7\u03bd"},
    {L"cs", L"Czech", L"\u010ce\u0161"},  {L"ro", L"Romanian", L"Rom\u00e2n"},   {L"hu", L"Hungarian", L"Magyar"},
};
const VizTransLangName* VizTransLangOf(const std::wstring& code) {
    for (auto const& l : kVizTransLangs)
        if (code == l.code) return &l;
    return nullptr;
}

// What script a text is mostly in: ideographs (Chinese), kana or hangul, or Latin letters.
void VizTransScripts(const std::wstring& t, int* han, int* kanaHangul, int* latin) {
    *han = *kanaHangul = *latin = 0;
    for (wchar_t c : t) {
        if (c >= 0x4E00 && c <= 0x9FFF) (*han)++;
        else if ((c >= 0x3040 && c <= 0x30FF) || (c >= 0xAC00 && c <= 0xD7AF)) (*kanaHangul)++;
        else if ((c >= L'a' && c <= L'z') || (c >= L'A' && c <= L'Z')) (*latin)++;
    }
}

// NetEase: its listeners' translation (tlyric) of the song, when it's in the language asked for. Theirs are almost
// all Chinese; English is taken when the text is plainly Latin and the song isn't.
std::wstring VizTransNetease(const std::wstring& artist, const std::wstring& title, int64_t durMs, const std::wstring& lang, const VizLyricSet& orig) {
    if (lang != L"zh" && lang != L"en") return L"";
    const std::string id = VizNeteaseFind(artist, title, durMs);
    if (id.empty()) return L"";
    const std::string lyr = VizHttpGet(L"https://music.163.com/api/song/lyric?lv=1&tv=-1&id=" + VizUtf8ToWide(id), L"Referer: https://music.163.com\r\nAccept: application/json");
    size_t tl = lyr.find("\"tlyric\"");
    std::wstring text;
    if (tl == std::string::npos || VizJsonString(lyr, "lyric", tl, &text) == std::string::npos || text.find(L'[') == std::wstring::npos) return L"";
    int han, kh, latin;
    VizTransScripts(text, &han, &kh, &latin);
    if (lang == L"zh") return han > latin && han > kh ? text : L"";
    std::wstring all;
    for (auto const& l : orig.lines) all += l.text;
    int oh, okh, ol;
    VizTransScripts(all, &oh, &okh, &ol);
    return latin > (han + kh) * 4 && (oh + okh) > ol ? text : L"";
}

// Genius: a page by one of its translator accounts ("Genius English Translations", "Genius Traducciones al
// Espanol" ...) for this song, in the language asked for. Romanizations aren't translations and are passed over.
std::wstring VizTransGenius(const std::wstring& artist, const std::wstring& title, const std::wstring& lang, const std::wstring& token) {
    const VizTransLangName* ln = VizTransLangOf(lang);
    if (!ln || token.empty()) return L"";
    const std::wstring auth = L"Authorization: Bearer " + token + L"\r\nAccept: application/json";
    const std::string body = VizHttpGet(L"https://api.genius.com/search?q=" + VizUtf8ToWide(VizUrlPart(artist + L" " + title + L" " + ln->english + L" translation")), auth.c_str());
    const std::wstring en = VizLyricsLower(ln->english), own = VizLyricsLower(ln->own), want = VizLyricsKeyOf(title);
    for (size_t at = 0; (at = body.find("\"result\":", at)) != std::string::npos; at++) {
        size_t end = VizJsonEnd(body, body.find('{', at));
        if (end == std::string::npos) break;
        const std::string r = body.substr(at, end - at);
        std::wstring t, u, an;
        VizJsonString(r, "title", 0, &t);
        VizJsonString(r, "url", 0, &u);
        if (size_t pa = r.find("\"primary_artist\""); pa != std::string::npos) VizJsonString(r, "name", pa, &an);
        const std::wstring anL = VizLyricsLower(an), tL = VizLyricsLower(t);
        if (anL.rfind(L"genius", 0) != 0 || anL.find(L"romaniz") != std::wstring::npos || tL.find(L"romaniz") != std::wstring::npos) continue;
        const bool inLang = anL.find(en) != std::wstring::npos || anL.find(own) != std::wstring::npos || tL.find(en) != std::wstring::npos ||
                            tL.find(own) != std::wstring::npos;
        if (!inLang || want.empty() || VizLyricsKeyOf(t).find(want) == std::wstring::npos) continue;
        if (u.rfind(L"https://genius.com/", 0) != 0) continue;
        return VizGeniusWords(u);
    }
    return L"";
}

// The translation laid against the song's lines: a timed one by its own times (each line takes the translation
// starting with it, within a third of a second); an untimed one line for line in order, blanks skipped, and only when
// the counts agree. Empty when it doesn't fit.
std::vector<std::wstring> VizTransMatch(const VizLyricSet& o, const VizLyricSet& t) {
    std::vector<std::wstring> out(o.lines.size());
    int want = 0, got = 0;
    for (auto const& l : o.lines)
        if (!l.text.empty()) want++;
    if (!want) return {};
    if (o.synced && t.synced) {
        size_t j = 0;
        for (size_t i = 0; i < o.lines.size(); i++) {
            if (o.lines[i].text.empty()) continue;
            while (j < t.lines.size() && t.lines[j].ms < o.lines[i].ms - 350) j++;
            for (size_t k = j; k < t.lines.size() && t.lines[k].ms <= o.lines[i].ms + 350; k++)
                if (!t.lines[k].text.empty()) {
                    out[i] = t.lines[k].text, got++;
                    break;
                }
        }
        if (got * 2 < want) return {};
    } else {
        std::vector<const std::wstring*> tl;
        for (auto const& l : t.lines)
            if (!l.text.empty()) tl.push_back(&l.text);
        if ((int)tl.size() != want) return {};
        size_t k = 0;
        for (size_t i = 0; i < o.lines.size(); i++)
            if (!o.lines[i].text.empty()) out[i] = *tl[k++], got++;
    }
    for (size_t i = 0; i < out.size(); i++)
        if (out[i] == o.lines[i].text) out[i].clear();  // (the same words: nothing to add)
    bool any = false;
    for (auto const& x : out) any |= !x.empty();
    return any ? out : std::vector<std::wstring>{};
}

// ---- Translate Lyrics: a model on this PC (machine translation, off) ----------------------------------------------
// Small OPUS-MT models (Helsinki-NLP, Marian; CC BY 4.0 or Apache 2.0, each its own folder) run with ONNX Runtime
// (MIT, its onnxruntime.dll loaded only when one is used). Into English only, as those models are. Tried after
// every source made by people; what it gives is marked on screen as machine translation. Lyrics worker thread only:
// nothing here runs while idle, and the drawing threads never wait on it.
// A model's folder: encoder_model*.onnx and decoder_model*.onnx (in it or in onnx\ or int8\), source.spm,
// vocab.json and config.json; named for its pair, "opus-mt-ru-en", or a family, "opus-mt-gmq-en".
#ifdef VIZ_HAVE_ORT
struct VizMtPieces {
    std::unordered_map<std::wstring, float> score;  // (the pieces a text may be cut into, with their scores)
    size_t longest = 1;
    float worst = 0.f;
};

// source.spm (SentencePiece's model, a protobuf): its pieces and scores. Normal and user-defined ones only.
bool VizMtReadSpm(const std::wstring& path, VizMtPieces* out) {
    std::string b;
    {
        HANDLE f = CreateFileW(path.c_str(), GENERIC_READ, FILE_SHARE_READ, nullptr, OPEN_EXISTING, 0, nullptr);
        if (f == INVALID_HANDLE_VALUE) return false;
        LARGE_INTEGER n{};
        GetFileSizeEx(f, &n);
        b.resize((size_t)n.QuadPart);
        DWORD got = 0;
        bool ok = n.QuadPart > 0 && n.QuadPart < (64ll << 20) && ReadFile(f, b.data(), (DWORD)b.size(), &got, nullptr) && got == b.size();
        CloseHandle(f);
        if (!ok) return false;
    }
    auto varint = [&](size_t& at, size_t end, uint64_t* v) {
        *v = 0;
        for (int sh = 0; at < end && sh < 64; sh += 7) {
            uint8_t c = (uint8_t)b[at++];
            *v |= (uint64_t)(c & 0x7F) << sh;
            if (!(c & 0x80)) return true;
        }
        return false;
    };
    auto skip = [&](size_t& at, size_t end, int wire) {
        uint64_t v;
        if (wire == 0) return varint(at, end, &v);
        if (wire == 1) return (at += 8) <= end;
        if (wire == 5) return (at += 4) <= end;
        if (wire == 2) return varint(at, end, &v) && (at += (size_t)v) <= end;
        return false;
    };
    size_t at = 0;
    while (at < b.size()) {
        uint64_t tag;
        if (!varint(at, b.size(), &tag)) return false;
        if (tag == 0x0A) {  // (pieces = 1, a SentencePiece each)
            uint64_t len;
            if (!varint(at, b.size(), &len) || at + len > b.size()) return false;
            size_t end = at + (size_t)len;
            std::string piece;
            float score = 0.f;
            uint64_t type = 1;
            while (at < end) {
                uint64_t t;
                if (!varint(at, end, &t)) return false;
                if (t == 0x0A) {
                    uint64_t l;
                    if (!varint(at, end, &l) || at + l > end) return false;
                    piece.assign(b, at, (size_t)l), at += (size_t)l;
                } else if (t == 0x15 && at + 4 <= end) {
                    memcpy(&score, b.data() + at, 4), at += 4;
                } else if (t == 0x18) {
                    if (!varint(at, end, &type)) return false;
                } else if (!skip(at, end, (int)(t & 7))) return false;
            }
            if (type == 1 || type == 4) {
                std::wstring w = VizUtf8ToWide(piece);
                if (!w.empty()) {
                    out->score[w] = type == 4 ? 0.f : score;
                    out->longest = std::max(out->longest, w.size());
                    out->worst = std::min(out->worst, score);
                }
            }
        } else if (!skip(at, b.size(), (int)(tag & 7))) return false;
    }
    return !out->score.empty();
}

// vocab.json: piece -> id (and back).
bool VizMtReadVocab(const std::wstring& path, std::unordered_map<std::wstring, int64_t>* ids, std::vector<std::wstring>* pieces) {
    std::wstring text;
    if (!VizReadTextFile(path, &text, 64ll << 20)) return false;  // (a vocabulary runs to several MB)
    size_t at = 0;
    for (;;) {
        size_t q = text.find(L'"', at);
        if (q == std::wstring::npos) break;
        std::wstring key;
        size_t i = q + 1;
        for (; i < text.size() && text[i] != L'"'; i++) {
            if (text[i] == L'\\' && i + 1 < text.size()) {
                wchar_t e = text[++i];
                if (e == L'u' && i + 4 < text.size()) key += (wchar_t)wcstoul(text.substr(i + 1, 4).c_str(), nullptr, 16), i += 4;
                else key += e == L'n' ? L'\n' : e == L't' ? L'\t' : e == L'r' ? L'\r' : e == L'b' ? L'\b' : e == L'f' ? L'\f' : e;
            } else key += text[i];
        }
        size_t colon = text.find(L':', i);
        if (colon == std::wstring::npos) break;
        int64_t id = _wcstoi64(text.c_str() + colon + 1, nullptr, 10);
        (*ids)[key] = id;
        if (id >= 0 && id < 1000000) {
            if ((size_t)id >= pieces->size()) pieces->resize((size_t)id + 1);
            (*pieces)[(size_t)id] = key;
        }
        at = text.find_first_of(L",}", colon);
        if (at == std::wstring::npos) break;
        at++;
    }
    return !ids->empty();
}

// A number from config.json ("key": n).
int64_t VizMtConfigInt(const std::wstring& cfg, const wchar_t* key, int64_t dflt) {
    const std::wstring k = std::wstring(L"\"") + key + L"\"";
    size_t at = cfg.find(k);
    if (at == std::wstring::npos) return dflt;
    at = cfg.find(L':', at);
    if (at == std::wstring::npos) return dflt;
    return _wcstoi64(cfg.c_str() + at + 1, nullptr, 10);
}

struct VizMtModel {
    std::wstring dir, name, pair;  // (pair: the source language or family, "ru", "gmq")
    std::wstring encoder, decoder, spm, vocab, config;
};

// The models in the folder: each subfolder with the files a model needs.
std::vector<VizMtModel> VizMtModels(const std::wstring& root) {
    std::vector<VizMtModel> out;
    if (root.empty()) return out;
    WIN32_FIND_DATAW fd;
    HANDLE h = FindFirstFileW((root + L"\\*").c_str(), &fd);
    if (h == INVALID_HANDLE_VALUE) return out;
    auto exists = [](const std::wstring& p) { return GetFileAttributesW(p.c_str()) != INVALID_FILE_ATTRIBUTES; };
    do {
        if (!(fd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) || fd.cFileName[0] == L'.') continue;
        VizMtModel m;
        m.dir = root + L"\\" + fd.cFileName;
        m.name = fd.cFileName;
        std::wstring low = VizLyricsLower(m.name);
        size_t en = low.find(L"-en");
        if (en == std::wstring::npos || low.rfind(L"opus-mt-", 0) != 0) continue;
        m.pair = low.substr(8, en - 8);
        if (m.pair.rfind(L"tc-big-", 0) == 0) m.pair = m.pair.substr(7);
        // (the smaller files first: quantized, then int8, then the full ones)
        for (const wchar_t* e : {L"\\onnx\\encoder_model_quantized.onnx", L"\\int8\\encoder_model.onnx", L"\\encoder_model_quantized.onnx",
                                 L"\\onnx\\encoder_model.onnx", L"\\encoder_model.onnx"})
            if (m.encoder.empty() && exists(m.dir + e)) m.encoder = m.dir + e;
        for (const wchar_t* d : {L"\\onnx\\decoder_model_merged_quantized.onnx", L"\\int8\\decoder_model.onnx", L"\\decoder_model_merged_quantized.onnx",
                                 L"\\onnx\\decoder_model_quantized.onnx", L"\\decoder_model_quantized.onnx", L"\\onnx\\decoder_model.onnx",
                                 L"\\decoder_model.onnx"})
            if (m.decoder.empty() && exists(m.dir + d)) m.decoder = m.dir + d;
        for (const wchar_t* sub : {L"", L"\\int8", L"\\onnx"}) {
            if (m.spm.empty() && exists(m.dir + sub + L"\\source.spm")) m.spm = m.dir + sub + L"\\source.spm";
            if (m.vocab.empty() && exists(m.dir + sub + L"\\vocab.json")) m.vocab = m.dir + sub + L"\\vocab.json";
            if (m.config.empty() && exists(m.dir + sub + L"\\config.json")) m.config = m.dir + sub + L"\\config.json";
        }
        if (!m.encoder.empty() && !m.decoder.empty() && !m.spm.empty() && !m.vocab.empty()) out.push_back(m);
    } while (FindNextFileW(h, &fd));
    FindClose(h);
    return out;
}

// The languages a family model takes (OPUS-MT's group codes).
bool VizMtPairTakes(const std::wstring& pair, const std::wstring& lang) {
    if (pair == lang) return true;
    static const struct { const wchar_t* group; const wchar_t* langs; } kGroups[] = {
        {L"gmq", L" sv da no nb nn is fo "}, {L"zle", L" ru uk be "}, {L"zlw", L" pl cs sk "},
        {L"zls", L" bg mk sr hr bs sl "},    {L"sla", L" ru uk be pl cs sk bg mk sr hr bs sl "},
        {L"cel", L" ga cy gd br kw gv "},    {L"romance", L" es fr it pt ro ca gl oc "}, {L"gem", L" de nl sv da no nb nn is fo "},
        {L"gmw", L" de nl lb fy af "},       {L"grk", L" el "},
    };
    for (auto const& g : kGroups)
        if (pair == g.group) return wcsstr(g.langs, (L" " + lang + L" ").c_str()) != nullptr;
    return false;
}

// The lyrics' language, from their letters and their commonest little words. "" when it looks like English or
// can't be told.
std::wstring VizMtGuessLanguage(const std::wstring& all, bool oneLine = false) {
    int kana = 0, han = 0, hangul = 0, cyr = 0, latin = 0;
    std::map<wchar_t, int> marks;
    for (wchar_t c : all) {
        if (c >= 0x3040 && c <= 0x30FF) kana++;
        else if (c >= 0x4E00 && c <= 0x9FFF) han++;
        else if (c >= 0xAC00 && c <= 0xD7AF) hangul++;
        else if (c >= 0x0400 && c <= 0x04FF) cyr++, marks[(wchar_t)towlower(c)]++;
        else if (iswalpha(c)) latin++, marks[(wchar_t)towlower(c)]++;
    }
    if (kana > 0 && kana * 10 >= han) return L"ja";
    if (hangul > latin) return L"ko";
    if (han > latin) return L"zh";
    auto has = [&](const wchar_t* set) {
        int n = 0;
        for (const wchar_t* p = set; *p; p++) n += marks.count(*p) ? marks[*p] : 0;
        return n;
    };
    if (cyr > latin) {
        if (has(L"іїєґ") > 0) return L"uk";
        if (has(L"ў") > 0) return L"be";
        if (has(L"ђћџљњј") > 0) return has(L"ѓќѕ") > 0 ? L"mk" : L"sr";
        if (has(L"ыэё") == 0 && has(L"ъ") > 2) return L"bg";
        return L"ru";
    }
    // (Latin: little words, each language's commonest, counted; letters of its own count more)
    std::wstring low = L" ";
    for (wchar_t c : all) low += iswalpha(c) ? (wchar_t)towlower(c) : L' ';
    low += L' ';
    static const struct { const wchar_t* lang; const wchar_t* words; const wchar_t* letters; } kLangs[] = {
        {L"en", L"the and you i to my me it is of in that your we", L""},
        {L"es", L"el la que de y en no mi me te lo los es por con", L"ñ¿¡"},
        {L"pt", L"o a que de e em nao meu me te do da os um uma", L"ãõ"},
        {L"fr", L"le la les et je tu de que pas une est dans mon", L"çêèàùœ"},
        {L"it", L"il la che di e non mi ti un una per sono io", L"ìò"},
        {L"de", L"der die das und ich du nicht ist ein mein mich zu", L"ßü"},
        {L"nl", L"de het een en ik je niet is van dat mijn", L""},
        {L"sv", L"och jag det att du inte en som på min mig är vi har", L"åäö"},
        {L"da", L"og jeg det at du ikke en som på min mig dig er vi har hvad", L"æøå"},
        {L"no", L"og jeg det at du ikke en som på min meg deg er vi har hva kveld ikkje eg", L"æøå"},
        {L"is", L"og ég það að þú ekki en sem á mig er", L"þð"},
        {L"fo", L"og eg tað at tú ikki ein sum á meg er", L"ð"},
        {L"fi", L"ja on ei se minä sinä että en olen mä sä", L"äö"},
        {L"pl", L"i nie w sie na ze to jest mnie ja ty jak", L"łąęśźżń"},
        {L"cs", L"a je to se na ze v ne jsem ty jak mi", L"řůě"},
        {L"sk", L"a je to sa na ze v nie som ty ako mi", L"ľĺŕô"},
        {L"hr", L"i je da se u na ne ti mi sam to", L"ćčđšž"},
        {L"sl", L"in je da se v na ne ti mi sem to", L"čšž"},
        {L"ga", L"agus an na mo is ar ag le do ta", L""},
        {L"cy", L"a y yn ac i fy dy ei o mae ar", L"ŵŷ"},
        {L"ro", L"si de la nu ca in eu tu ma te sa", L"ășțîâ"},
    };
    std::wstring best;
    double bestScore = 0, enScore = 0;
    for (auto const& L : kLangs) {
        double score = 0;
        std::wstring ws = L.words;
        for (size_t s = 0; s < ws.size();) {
            size_t e = ws.find(L' ', s);
            if (e == std::wstring::npos) e = ws.size();
            const std::wstring w = L" " + ws.substr(s, e - s) + L" ";
            for (size_t at = 0; (at = low.find(w, at)) != std::wstring::npos; at += w.size() - 1) score += 1;
            s = e + 1;
        }
        score += has(L.letters) * 3.0;
        if (!wcscmp(L.lang, L"en")) enScore = score;
        if (score > bestScore) bestScore = score, best = L.lang;
    }
    if (best == L"en") return L"";
    if (oneLine ? (bestScore < 2 || bestScore < enScore * 1.5 + 0.5) : (bestScore < 4 || bestScore < enScore * 1.2)) return L"";
    return best;
}

// ONNX Runtime, loaded once, from the folder set (or Tourne Desktop's own, or the models folder).
const OrtApi* g_mtOrt = nullptr;
OrtEnv* g_mtEnv = nullptr;
std::mutex g_mtOrtLock;

bool VizMtLoadOrt(const std::wstring& runtimeDir, const std::wstring& modelsDir, std::wstring* why) {
    std::lock_guard<std::mutex> hold(g_mtOrtLock);
    if (g_mtOrt) return true;
    std::vector<std::wstring> dirs;
    if (!runtimeDir.empty()) dirs.push_back(runtimeDir);
    wchar_t base[MAX_PATH] = L"";
    if (ExpandEnvironmentStringsW(L"%LOCALAPPDATA%\\Tourne\\Desktop\\models\\runtime", base, MAX_PATH)) dirs.push_back(base);
    if (!modelsDir.empty()) dirs.push_back(modelsDir);
    for (auto const& d : dirs) {
        const std::wstring dll = d + L"\\onnxruntime.dll";
        if (GetFileAttributesW(dll.c_str()) == INVALID_FILE_ATTRIBUTES) continue;
        LoadLibraryExW((d + L"\\DirectML.dll").c_str(), nullptr, LOAD_WITH_ALTERED_SEARCH_PATH);  // (its own, when it has one)
        HMODULE lib = LoadLibraryExW(dll.c_str(), nullptr, LOAD_WITH_ALTERED_SEARCH_PATH);
        auto getBase = lib ? (const OrtApiBase*(ORT_API_CALL*)())(void*)GetProcAddress(lib, "OrtGetApiBase") : nullptr;
        const OrtApi* api = getBase ? getBase()->GetApi(ORT_API_VERSION) : nullptr;
        if (!api) {
            *why = L"onnxruntime.dll in " + d + L" is too old or not a 64-bit build";
            continue;
        }
        OrtEnv* env = nullptr;
        if (OrtStatus* st = api->CreateEnv(ORT_LOGGING_LEVEL_ERROR, "TourneTable", &env)) {
            *why = VizUtf8ToWide(api->GetErrorMessage(st));
            api->ReleaseStatus(st);
            continue;
        }
        g_mtOrt = api, g_mtEnv = env;
        return true;
    }
    if (why->empty()) *why = L"no onnxruntime.dll found (the Runtime Folder setting, or Tourne Desktop's models\\runtime)";
    return false;
}

// One model, open for a song's lines.
struct VizMtSession {
    const OrtApi* api = nullptr;
    OrtSession *enc = nullptr, *dec = nullptr;
    OrtMemoryInfo* mem = nullptr;
    OrtAllocator* alloc = nullptr;
    VizMtPieces pieces;
    std::unordered_map<std::wstring, int64_t> ids;
    std::vector<std::wstring> byId;
    int64_t eos = 0, pad = 0, unk = 1, start = 0;
    int layers = 6, heads = 8, headDim = 64;
    std::vector<std::string> decIn, decOut, encOut;
    bool cached = false;  // (the decoder takes the past: one new word a step)
    std::wstring error;

    bool Ok(OrtStatus* st) {
        if (!st) return true;
        if (error.empty()) error = VizUtf8ToWide(api->GetErrorMessage(st));
        api->ReleaseStatus(st);
        return false;
    }
    ~VizMtSession() {
        if (!api) return;
        if (enc) api->ReleaseSession(enc);
        if (dec) api->ReleaseSession(dec);
        if (mem) api->ReleaseMemoryInfo(mem);
    }
    bool Open(const VizMtModel& m) {
        api = g_mtOrt;
        if (!VizMtReadSpm(m.spm, &pieces) || !VizMtReadVocab(m.vocab, &ids, &byId)) return error = L"its source.spm or vocab.json can't be read", false;
        std::wstring cfg;
        if (!m.config.empty()) VizReadTextFile(m.config, &cfg);
        eos = VizMtConfigInt(cfg, L"eos_token_id", ids.count(L"</s>") ? ids[L"</s>"] : 0);
        pad = VizMtConfigInt(cfg, L"pad_token_id", ids.count(L"<pad>") ? ids[L"<pad>"] : (int64_t)byId.size() - 1);
        start = VizMtConfigInt(cfg, L"decoder_start_token_id", pad);
        unk = ids.count(L"<unk>") ? ids[L"<unk>"] : 1;
        layers = (int)VizMtConfigInt(cfg, L"decoder_layers", 6);
        heads = (int)VizMtConfigInt(cfg, L"decoder_attention_heads", 8);
        headDim = (int)(VizMtConfigInt(cfg, L"d_model", 512) / std::max(1, heads));
        OrtSessionOptions* so = nullptr;
        if (!Ok(api->CreateSessionOptions(&so))) return false;
        api->SetIntraOpNumThreads(so, 2);  // (two cores at most: the Table and the PC keep the rest)
        api->SetInterOpNumThreads(so, 1);
        api->SetSessionGraphOptimizationLevel(so, ORT_ENABLE_ALL);
        bool ok = Ok(api->CreateSession(g_mtEnv, m.encoder.c_str(), so, &enc)) && Ok(api->CreateSession(g_mtEnv, m.decoder.c_str(), so, &dec));
        api->ReleaseSessionOptions(so);
        if (!ok) return false;
        if (!Ok(api->CreateCpuMemoryInfo(OrtArenaAllocator, OrtMemTypeDefault, &mem)) || !Ok(api->GetAllocatorWithDefaultOptions(&alloc))) return false;
        auto names = [&](OrtSession* s, bool in, std::vector<std::string>* out) {
            size_t n = 0;
            if (!Ok(in ? api->SessionGetInputCount(s, &n) : api->SessionGetOutputCount(s, &n))) return false;
            for (size_t i = 0; i < n; i++) {
                char* nm = nullptr;
                if (!Ok(in ? api->SessionGetInputName(s, i, alloc, &nm) : api->SessionGetOutputName(s, i, alloc, &nm))) return false;
                out->push_back(nm);
                api->AllocatorFree(alloc, nm);
            }
            return true;
        };
        if (!names(dec, true, &decIn) || !names(dec, false, &decOut) || !names(enc, false, &encOut)) return false;
        for (auto const& n : decIn) cached |= n.rfind("past_key_values", 0) == 0;
        return true;
    }

    // A line cut into the model's pieces (the most likely cut), then their ids, then the end.
    std::vector<int64_t> Encode(const std::wstring& line) {
        std::wstring t = L"▁";
        bool space = false;
        for (wchar_t c : line) {
            if (iswspace(c)) space = true;
            else {
                if (space && t.size() > 1) t += L'▁';
                space = false, t += c;
            }
        }
        const size_t n = t.size();
        std::vector<float> best(n + 1, -1e30f);
        std::vector<size_t> from(n + 1, 0);
        best[0] = 0;
        for (size_t i = 0; i < n; i++) {
            if (best[i] <= -1e29f) continue;
            bool any = false;
            for (size_t len = 1; len <= pieces.longest && i + len <= n; len++) {
                auto it = pieces.score.find(t.substr(i, len));
                if (it == pieces.score.end()) continue;
                any = true;
                if (best[i] + it->second > best[i + len]) best[i + len] = best[i] + it->second, from[i + len] = i;
            }
            if (!any && best[i] + pieces.worst - 10.f > best[i + 1]) best[i + 1] = best[i] + pieces.worst - 10.f, from[i + 1] = i;  // (unknown)
        }
        std::vector<int64_t> out;
        for (size_t at = n; at > 0; at = from[at]) {
            auto it = ids.find(t.substr(from[at], at - from[at]));
            out.push_back(it == ids.end() ? unk : it->second);
        }
        std::reverse(out.begin(), out.end());
        if (out.size() > 200) out.resize(200);
        out.push_back(eos);
        return out;
    }

    OrtValue* Tensor(std::vector<int64_t> const& shape, ONNXTensorElementDataType type, void* data, size_t bytes) {
        OrtValue* v = nullptr;
        if (data) Ok(api->CreateTensorWithDataAsOrtValue(mem, data, bytes, shape.data(), shape.size(), type, &v));
        else Ok(api->CreateTensorAsOrtValue(alloc, shape.data(), shape.size(), type, &v));
        return v;
    }

    // One line in, its translation out (greedy, the likeliest word each step). "" when it fails.
    std::wstring Translate(const std::wstring& line) {
        std::vector<int64_t> src = Encode(line), mask(src.size(), 1);
        const int64_t n = (int64_t)src.size();
        OrtValue* inIds = Tensor({1, n}, ONNX_TENSOR_ELEMENT_DATA_TYPE_INT64, src.data(), src.size() * 8);
        OrtValue* inMask = Tensor({1, n}, ONNX_TENSOR_ELEMENT_DATA_TYPE_INT64, mask.data(), mask.size() * 8);
        if (!inIds || !inMask) return L"";
        const char* encInNames[2] = {"input_ids", "attention_mask"};
        const OrtValue* encIn[2] = {inIds, inMask};
        const char* encOutName = encOut.empty() ? "last_hidden_state" : encOut[0].c_str();
        OrtValue* hidden = nullptr;
        bool ok = Ok(api->Run(enc, nullptr, encInNames, encIn, 2, &encOutName, 1, &hidden));
        api->ReleaseValue(inIds);
        if (!ok) return api->ReleaseValue(inMask), L"";
        std::map<std::string, OrtValue*> past;  // (the decoder's past, named as its inputs)
        if (cached)
            for (auto const& nm : decIn)
                if (nm.rfind("past_key_values", 0) == 0) past[nm] = Tensor({1, heads, 0, headDim}, ONNX_TENSOR_ELEMENT_DATA_TYPE_FLOAT, nullptr, 0);
        std::vector<int64_t> outIds{start};
        const int64_t most = std::min<int64_t>(256, n * 3 + 10);
        while ((int64_t)outIds.size() < most) {
            const bool first = outIds.size() == 1;
            std::vector<int64_t> step = cached && !first ? std::vector<int64_t>{outIds.back()} : outIds;
            OrtValue* stepIds = Tensor({1, (int64_t)step.size()}, ONNX_TENSOR_ELEMENT_DATA_TYPE_INT64, step.data(), step.size() * 8);
            bool branch = cached && !first;
            OrtValue* useCache = Tensor({1}, ONNX_TENSOR_ELEMENT_DATA_TYPE_BOOL, &branch, sizeof(branch));
            std::vector<const char*> inNames;
            std::vector<const OrtValue*> ins;
            for (auto const& nm : decIn) {
                const OrtValue* v = nm == "input_ids" ? stepIds : nm == "encoder_attention_mask" ? inMask : nm == "encoder_hidden_states" ? hidden
                                  : nm == "use_cache_branch" ? useCache : past.count(nm) ? past[nm] : nullptr;
                if (!v) {
                    error = L"its decoder wants an input this doesn't know: " + VizUtf8ToWide(nm), ok = false;
                    break;
                }
                inNames.push_back(nm.c_str()), ins.push_back(v);
            }
            std::vector<const char*> outNames;
            for (auto const& nm : decOut) outNames.push_back(nm.c_str());
            std::vector<OrtValue*> outs(outNames.size(), nullptr);
            if (ok) ok = Ok(api->Run(dec, nullptr, inNames.data(), ins.data(), ins.size(), outNames.data(), outNames.size(), outs.data()));
            api->ReleaseValue(stepIds), api->ReleaseValue(useCache);
            if (!ok) {
                for (auto* o : outs)
                    if (o) api->ReleaseValue(o);
                break;
            }
            int64_t next = eos;
            for (size_t i = 0; i < decOut.size(); i++) {
                if (decOut[i] == "logits") {
                    float* lg = nullptr;
                    OrtTensorTypeAndShapeInfo* info = nullptr;
                    size_t dims = 0;
                    int64_t shape[3] = {};
                    api->GetTensorMutableData(outs[i], (void**)&lg);
                    api->GetTensorTypeAndShape(outs[i], &info);
                    api->GetDimensionsCount(info, &dims);
                    if (dims == 3) api->GetDimensions(info, shape, 3);
                    api->ReleaseTensorTypeAndShapeInfo(info);
                    if (lg && dims == 3) {
                        const float* last = lg + (shape[1] - 1) * shape[2];
                        float top = -1e30f;
                        for (int64_t v = 0; v < shape[2]; v++)
                            if (v != pad && last[v] > top) top = last[v], next = v;
                    }
                    api->ReleaseValue(outs[i]);
                } else if (cached && decOut[i].rfind("present", 0) == 0) {
                    // (present.N.decoder.key is the next step's past_key_values.N.decoder.key; the encoder's past
                    // is kept from the first step, as the merged model gives it only then)
                    std::string to = "past_key_values" + decOut[i].substr(7);
                    const bool encoderPart = to.find(".encoder.") != std::string::npos;
                    if (past.count(to) && (!encoderPart || first)) {
                        api->ReleaseValue(past[to]);
                        past[to] = outs[i];
                    } else api->ReleaseValue(outs[i]);
                } else api->ReleaseValue(outs[i]);
            }
            if (next == eos) break;
            outIds.push_back(next);
            // (a run of the same few words again and again: stopped)
            const size_t k = outIds.size();
            if (k > 12 && std::equal(outIds.end() - 4, outIds.end(), outIds.end() - 8) && std::equal(outIds.end() - 4, outIds.end(), outIds.end() - 12)) {
                outIds.resize(k - 8);
                break;
            }
        }
        for (auto& kv : past)
            if (kv.second) api->ReleaseValue(kv.second);
        api->ReleaseValue(hidden), api->ReleaseValue(inMask);
        if (!ok) return L"";
        std::wstring out;
        for (size_t i = 1; i < outIds.size(); i++) {
            const int64_t id = outIds[i];
            if (id < 0 || (size_t)id >= byId.size() || id == pad || id == unk) continue;
            out += byId[(size_t)id];
        }
        for (auto& c : out)
            if (c == L'▁') c = L' ';
        size_t a = out.find_first_not_of(L' '), b = out.find_last_not_of(L' ');
        return a == std::wstring::npos ? L"" : out.substr(a, b - a + 1);
    }
};

// The models folder in use: the setting, else %LOCALAPPDATA%\Tourne\Table\Models\Translate.
std::wstring VizMtModelsDir() {
    if (!g_settings.lyrTransModels.empty()) return g_settings.lyrTransModels;
    wchar_t p[MAX_PATH] = L"";
    return ExpandEnvironmentStringsW(L"%LOCALAPPDATA%\\Tourne\\Table\\Models\\Translate", p, MAX_PATH) ? p : L"";
}

// The song's lines put into English by a model on this PC, each line once (choruses come again). Empty when no model
// fits its language, or it isn't English that's asked for. Lyrics worker thread.
// The models installed, as one line (for the kept translations: a model added or taken away means made again).
std::wstring VizMtSignature() {
    std::vector<std::wstring> names;
    for (auto const& m : VizMtModels(VizMtModelsDir())) names.push_back(VizLyricsLower(m.name));
    std::sort(names.begin(), names.end());
    std::wstring out;
    for (auto const& n : names) out += (out.empty() ? L"" : L",") + n;
    return out;
}

// The song's lines put into English by models on this PC. Line by line: a line's script tells its language first
// (Cyrillic ones share the song's Cyrillic language, kana ones are Japanese); a Latin-script line goes by its own
// little words and letters, and is left as written when it looks English, is short, or can't be told. Each language
// its own model, opened in turn; each line once (choruses come again). Empty when nothing was put into English.
// Lyrics worker thread.
std::vector<std::wstring> VizMtTranslate(const VizLyricSet& orig, const std::wstring& lang, std::wstring* model, bool* failed = nullptr) {
    if (lang != L"en") return {};
    const size_t n = orig.lines.size();
    auto script = [](const std::wstring& t, int* cyr, int* kana, int* han, int* hangul, int* latin) {
        *cyr = *kana = *han = *hangul = *latin = 0;
        for (wchar_t c : t) {
            if (c >= 0x0400 && c <= 0x04FF) (*cyr)++;
            else if (c >= 0x3040 && c <= 0x30FF) (*kana)++;
            else if (c >= 0x4E00 && c <= 0x9FFF) (*han)++;
            else if (c >= 0xAC00 && c <= 0xD7AF) (*hangul)++;
            else if (iswalpha(c)) (*latin)++;
        }
    };
    std::wstring cyrAll, kanaAll;
    for (auto const& l : orig.lines) {
        int cy, ka, ha, hg, la;
        script(l.text, &cy, &ka, &ha, &hg, &la);
        if (cy) cyrAll += l.text + L"\n";
        if (ka || ha) kanaAll += l.text + L"\n";
    }
    const std::wstring cyrLang = cyrAll.empty() ? L"" : VizMtGuessLanguage(cyrAll);
    const bool japanese = !kanaAll.empty() && VizMtGuessLanguage(kanaAll) == L"ja";
    std::vector<std::wstring> lineLang(n);
    std::map<std::wstring, int> count;
    int left = 0;
    for (size_t i = 0; i < n; i++) {
        const std::wstring& t = orig.lines[i].text;
        if (t.find_first_not_of(L" \t") == std::wstring::npos) continue;
        int cy, ka, ha, hg, la;
        script(t, &cy, &ka, &ha, &hg, &la);
        // (a line with any of another script's words goes whole: English words in it come through as they are)
        if (cy && cy * 3 >= la) lineLang[i] = cyrLang;
        else if ((ka || ha) && (ka + ha) * 3 >= la) lineLang[i] = japanese ? L"ja" : L"";
        else if (hg) lineLang[i] = L"";
        else lineLang[i] = VizMtGuessLanguage(t, true);
        if (lineLang[i].empty()) left++;
        else count[lineLang[i]]++;
    }
    if (count.empty()) return {};
    const std::wstring dir = VizMtModelsDir();
    std::vector<VizMtModel> models = VizMtModels(dir);
    auto pickFor = [&](const std::wstring& src) -> const VizMtModel* {
        for (auto const& m : models)  // (a model for the one language before a family's)
            if (m.pair == src) return &m;
        for (auto const& m : models)
            if (VizMtPairTakes(m.pair, src)) return &m;
        return nullptr;
    };
    std::wstring why;
    bool ortTried = false, ortOk = false;
    const ULONGLONG t0 = GetTickCount64();
    std::vector<std::wstring> out(n);
    std::wstring used, summary;
    int lines = 0;
    for (auto const& kv : count) {
        const VizMtModel* pick = pickFor(kv.first);
        summary += (summary.empty() ? L"" : L", ") + kv.first + L" " + std::to_wstring(kv.second);
        if (!pick) {
            Wh_Log(L"[Lyrics] machine translation: no model for %s in %s", kv.first.c_str(), dir.c_str());
            continue;
        }
        if (!ortTried) {
            ortTried = true, ortOk = VizMtLoadOrt(g_settings.lyrTransRuntime, dir, &why);
            if (!ortOk) Wh_Log(L"[Lyrics] machine translation: %s", why.c_str());
        }
        if (!ortOk) {
            if (failed) *failed = true;
            break;
        }
        VizMtSession sess;  // (one language's model at a time: opened, used for its lines, let go)
        if (!sess.Open(*pick)) {
            Wh_Log(L"[Lyrics] machine translation: %s can't be opened: %s", pick->name.c_str(), sess.error.c_str());
            if (failed) *failed = true;
            continue;
        }
        used += (used.empty() ? L"" : L", ") + pick->name;
        std::unordered_map<std::wstring, std::wstring> done;
        for (size_t i = 0; i < n; i++) {
            if (lineLang[i] != kv.first) continue;
            if (g_lyricsStop.load()) return {};
            const std::wstring& t = orig.lines[i].text;
            auto it = done.find(t);
            if (it == done.end()) it = done.emplace(t, sess.Translate(t)).first, lines++;
            out[i] = it->second == t ? L"" : it->second;
            if (!sess.error.empty()) break;
        }
        if (!sess.error.empty()) {
            Wh_Log(L"[Lyrics] machine translation (%s): %s", pick->name.c_str(), sess.error.c_str());
            if (failed) *failed = true;
        }
    }
    bool any = false;
    for (auto const& x : out) any |= !x.empty();
    Wh_Log(L"[Lyrics] machine translation: %d lines put into English (%s; %d left as written) with %s in %llu ms", lines, summary.c_str(), left,
           used.empty() ? L"no model" : used.c_str(), GetTickCount64() - t0);
    *model = used;
    return any ? out : std::vector<std::wstring>{};
}
#endif  // VIZ_HAVE_ORT

// The playing song's translation: kept ones first (the cache, then your folder's "<name>.<lang>.lrc"), then each
// source that's on, in turn. What's found is kept (with where it came from); "none" is remembered for a week for the
// sources that were on then. Lyrics worker thread.
std::vector<std::wstring> VizLyricsTranslate(const VizLyricSet& orig, const std::wstring& artist, const std::wstring& title, int64_t durMs,
                                             std::wstring* from) {
    const std::wstring lang = g_settings.lyrTransLang;
    if (lang.empty() || orig.lines.empty()) return {};
    const std::wstring name = VizLyricsFileName(artist.empty() ? title : artist + L" - " + title), cache = VizLyricsCacheDir();
    const std::wstring kept = cache.empty() ? L"" : cache + L"\\" + name + L"." + lang + L".lrc";
    std::wstring text;
    auto withFrom = [](std::wstring t, std::wstring* f) {  // ("[tourne-from:...]" on the first line, when kept)
        if (t.rfind(L"[tourne-from:", 0) == 0) {
            size_t e = t.find(L']');
            if (e != std::wstring::npos) *f = t.substr(13, e - 13), t.erase(0, t.find(L'\n', e) == std::wstring::npos ? t.size() : t.find(L'\n', e) + 1);
        }
        return t;
    };
    if (!kept.empty() && VizReadTextFile(kept, &text)) {
        *from = L"kept";
        std::wstring body = withFrom(text, from);
        bool stale = false;
        if (body.rfind(L"[tourne-models:", 0) == 0) {  // (a machine translation: which models made it)
            size_t e = body.find(L']');
            const std::wstring made = e == std::wstring::npos ? L"" : body.substr(15, e - 15);
            body.erase(0, body.find(L'\n') == std::wstring::npos ? body.size() : body.find(L'\n') + 1);
#ifdef VIZ_HAVE_ORT
            stale = !g_settings.lyrTransMachine || made != VizMtSignature();
#else
            stale = true;
#endif
        }
        if (!stale) return VizTransMatch(orig, VizParseLrc(body));
    }
    if (g_settings.lyrTransFiles && !g_settings.lyricsFolder.empty())
        for (const std::wstring& n : {name, VizLyricsFileName(title)})
            if (VizReadTextFile(g_settings.lyricsFolder + L"\\" + n + L"." + lang + L".lrc", &text)) {
                *from = L"your file";
                return VizTransMatch(orig, VizParseLrc(text));
            }
    const bool genius = g_settings.lyrTransGenius && !g_settings.lyrGeniusToken.empty();
#ifdef VIZ_HAVE_ORT
    const bool machine = g_settings.lyrTransMachine;
#else
    const bool machine = false;
#endif
    const std::wstring sources = std::wstring(g_settings.lyrTransNetease ? L"n" : L"") + (genius ? L"g" : L"") + (machine ? L"m" : L"");
    if (sources.empty() || cache.empty()) return {};
    const std::wstring none = cache + L"\\" + name + L"." + lang + L".none";
    {
        WIN32_FILE_ATTRIBUTE_DATA a{};
        FILETIME nowFt;
        GetSystemTimeAsFileTime(&nowFt);
        std::wstring noneFor;
        if (GetFileAttributesExW(none.c_str(), GetFileExInfoStandard, &a) && VizReadTextFile(none, &noneFor) && noneFor == sources) {
            const uint64_t now = ULARGE_INTEGER{{nowFt.dwLowDateTime, nowFt.dwHighDateTime}}.QuadPart,
                           at = ULARGE_INTEGER{{a.ftLastWriteTime.dwLowDateTime, a.ftLastWriteTime.dwHighDateTime}}.QuadPart;
            if ((now - at) / 10000000ull < 7ull * 86400) return {};
        }
    }
    std::vector<std::wstring> out;
    bool machineFailed = false;
    for (wchar_t src : sources) {
        if (g_lyricsStop.load()) return {};
#ifdef VIZ_HAVE_ORT
        if (src == L'm') {  // (a model on this PC: kept as lines at the song's own times, so it isn't made again)
            std::wstring model;
            out = VizMtTranslate(orig, lang, &model, &machineFailed);
            if (out.empty()) continue;
            *from = L"machine translation";
            std::wstring lrc;
            for (size_t i = 0; i < orig.lines.size(); i++) {
                if (orig.synced) {
                    wchar_t at[24];
                    const int64_t ms = std::max<int64_t>(0, orig.lines[i].ms);
                    swprintf_s(at, L"[%02lld:%02lld.%02lld]", ms / 60000, ms / 1000 % 60, ms / 10 % 100);
                    lrc += at;
                }
                lrc += (out[i].empty() ? orig.lines[i].text : out[i]) + L"\n";
            }
            VizWriteTextFile(kept, L"[tourne-from:" + *from + L"]\n[tourne-models:" + VizMtSignature() + L"]\n" + lrc);
            Wh_Log(L"[Lyrics] %s: a machine translation (%s) with %s", name.c_str(), lang.c_str(), model.c_str());
            return out;
        }
#endif
        text = src == L'n' ? VizTransNetease(artist, title, durMs, lang, orig) : VizTransGenius(artist, title, lang, g_settings.lyrGeniusToken);
        if (text.empty()) continue;
        out = VizTransMatch(orig, VizParseLrc(text));
        if (out.empty()) continue;  // (found, but it doesn't fit these lyrics)
        *from = src == L'n' ? L"NetEase" : L"Genius";
        VizWriteTextFile(kept, L"[tourne-from:" + *from + L"]\n" + text);
        Wh_Log(L"[Lyrics] %s: a translation (%s) from %s", name.c_str(), lang.c_str(), from->c_str());
        return out;
    }
    if (sources.find(L'm') == std::wstring::npos) VizWriteTextFile(none, sources);
    Wh_Log(L"[Lyrics] %s: no translation (%s) found", name.c_str(), lang.c_str());
    if (machineFailed) {  // (a model for these words is there but couldn't be opened or run: said under the lyrics)
        *from = L"machine translation not available";
        return std::vector<std::wstring>(orig.lines.size());
    }
    return {};
}

void VizListenArm(const std::wstring& key);
void VizListenShutdown();

void VizLyricsWorker() {
    for (;;) {
        WaitForSingleObject(g_lyricsWake, INFINITE);
        if (g_lyricsStop.load()) return;
        std::wstring artist, title, album;
        {
            std::lock_guard<std::mutex> lock(g_lyricsMutex);
            artist = g_lyricsWantArtist, title = g_lyricsWantTitle, album = g_lyricsWantAlbum;
        }
        const std::wstring key = VizLyricsLower(artist) + L"\n" + VizLyricsLower(title);
        auto publish = [&](VizLyricSet&& set, const wchar_t* from) {
            std::lock_guard<std::mutex> lock(g_lyricsMutex);
            if (VizLyricsLower(g_lyricsWantArtist) + L"\n" + VizLyricsLower(g_lyricsWantTitle) != key) return;  // (moved on)
            if (set.lines.empty()) g_lyrics = nullptr;
            else {
                set.key = key, set.from = from;
                g_lyrics = std::make_shared<const VizLyricSet>(std::move(set));
            }
            g_lyricsSerial.fetch_add(1);
        };
        // Translate Lyrics: once the words are up, their translation (if any), as a copy of them with it added.
        auto translate = [&] {
            std::shared_ptr<const VizLyricSet> shown;
            {
                std::lock_guard<std::mutex> lock(g_lyricsMutex);
                shown = g_lyrics;
            }
            if (!g_settings.lyrTranslate || !shown || shown->key != key || g_lyricsStop.load()) return;
            const int64_t s0 = g_tlStart.load(), e0 = g_tlEnd.load();
            const int64_t dur = g_tlValid.load() && e0 > s0 ? (e0 - s0) / 10000 : 0;
            std::wstring tFrom;
            std::vector<std::wstring> tr = VizLyricsTranslate(*shown, artist, title, dur, &tFrom);
            if (tr.empty() || tFrom == L"machine translation not available") VizListenArm(shown->key);  // (none: heard from the sound, when that's on)
            if (tr.empty()) return;
            auto withIt = std::make_shared<VizLyricSet>(*shown);
            withIt->trans = std::move(tr), withIt->transFrom = tFrom;
            std::lock_guard<std::mutex> lock(g_lyricsMutex);
            if (g_lyrics != shown) return;  // (moved on)
            g_lyrics = withIt;
            g_lyricsSerial.fetch_add(1);
        };
        if (title.empty()) {
            publish(VizLyricSet(), L"");
            continue;
        }
        const std::wstring name = VizLyricsFileName(artist.empty() ? title : artist + L" - " + title);
        const std::wstring cache = VizLyricsCacheDir();
        std::wstring text;
        // 1. The cache.
        if (!cache.empty() && VizReadTextFile(cache + L"\\" + name + L".lrc", &text)) {
            Wh_Log(L"[Lyrics] %s: from the cache", name.c_str());
            publish(VizParseLrc(text), L"cache");
            translate();
            continue;
        }
        // 2. Your folder.
        bool found = false;
        if (!g_settings.lyricsFolder.empty()) {
            for (const std::wstring& n : {name, VizLyricsFileName(title)}) {
                if (VizReadTextFile(g_settings.lyricsFolder + L"\\" + n + L".lrc", &text)) {
                    Wh_Log(L"[Lyrics] %s: from your folder", name.c_str());
                    publish(VizParseLrc(text), L"folder");
                    translate();
                    found = true;
                    break;
                }
            }
        }
        if (found) continue;
        // 3. Online, only when asked for (each source its own switch); "not found" remembered for a week, for the
        // sources that were on then (turning another on asks again).
        const std::wstring sources = std::wstring(g_settings.lyricsOnline ? L"l" : L"") + (g_settings.lyrSrcLrclibLoose ? L"o" : L"") +
                                     (g_settings.lyrSrcNetease ? L"n" : L"") + (g_settings.lyrSrcGenius && !g_settings.lyrGeniusToken.empty() ? L"g" : L"") +
                                     (g_settings.lyrSrcMySite && !g_settings.lyrMySiteUrl.empty() ? L"m" : L"");
        if (!sources.empty() && !cache.empty()) {
            const std::wstring none = cache + L"\\" + name + L".none";
            WIN32_FILE_ATTRIBUTE_DATA a{};
            FILETIME nowFt;
            GetSystemTimeAsFileTime(&nowFt);
            const auto age = [&](FILETIME t) {
                return (int64_t)(((ULARGE_INTEGER{{nowFt.dwLowDateTime, nowFt.dwHighDateTime}}.QuadPart) -
                                  (ULARGE_INTEGER{{t.dwLowDateTime, t.dwHighDateTime}}.QuadPart)) / 10000000ull);
            };
            std::wstring noneFor;
            const bool noneKnown = GetFileAttributesExW(none.c_str(), GetFileExInfoStandard, &a) && age(a.ftLastWriteTime) < 7 * 86400 &&
                                   VizReadTextFile(none, &noneFor) && (noneFor == sources || (noneFor.empty() && sources == L"l"));
            if (!noneKnown) {
                // Wait a moment for the player to report the length (it picks the right version of a song).
                auto durNow = [] {
                    int64_t s = g_tlStart.load(), e = g_tlEnd.load();
                    return g_tlValid.load() && e > s ? (e - s) / 10000 : (int64_t)0;
                };
                for (int i = 0; i < 20 && durNow() <= 0 && !g_lyricsStop.load(); i++) Sleep(100);
                bool reached = false;
                std::wstring askArtist = artist, askTitle = title;
                if (g_settings.lyrFixLastfm && !g_settings.lyrLastfmKey.empty()) VizLyricsLastfmFix(&askArtist, &askTitle, g_settings.lyrLastfmKey);
                const int64_t dur = durNow();
                const wchar_t* from = L"";
                text.clear();
                if (g_settings.lyricsOnline) text = VizLyricsOnline(askArtist, askTitle, album, dur, &reached), from = L"lrclib.net";
                if (text.empty() && g_settings.lyrSrcLrclibLoose && !g_lyricsStop) text = VizLyricsLrclibLoose(askArtist, askTitle, dur), from = L"lrclib.net (looser)";
                if (text.empty() && g_settings.lyrSrcNetease && !g_lyricsStop) text = VizLyricsNetease(askArtist, askTitle, dur), from = L"NetEase";
                if (text.empty() && g_settings.lyrSrcGenius && !g_settings.lyrGeniusToken.empty() && !g_lyricsStop)
                    text = VizLyricsGenius(askArtist, askTitle, g_settings.lyrGeniusToken), from = L"Genius";
                if (text.empty() && g_settings.lyrSrcMySite && !g_settings.lyrMySiteUrl.empty() && !g_lyricsStop)
                    text = VizLyricsMySite(g_settings.lyrMySiteUrl, askArtist, askTitle, album, dur), from = L"your site";
                if (!text.empty()) {
                    VizWriteTextFile(cache + L"\\" + name + L".lrc", text);
                    Wh_Log(L"[Lyrics] %s: found online (%s)", name.c_str(), from);
                    publish(VizParseLrc(text), L"online");
                    translate();
                    continue;
                }
                if (reached || sources != L"l") VizWriteTextFile(none, sources);
                Wh_Log(L"[Lyrics] %s: %s", name.c_str(), reached || sources != L"l" ? L"none online" : L"lrclib.net couldn't be reached");
            }
        }
        publish(VizLyricSet(), L"");
    }
}

// A new track (or Lyrics turned on): look for its lyrics. UI or media thread.
void VizLyricsTrack(const std::wstring& artist, const std::wstring& title, const std::wstring& album) {
    if (!g_settings.lyricsEnabled) return;
    {
        std::lock_guard<std::mutex> lock(g_lyricsMutex);
        if (g_lyricsWantArtist == artist && g_lyricsWantTitle == title && g_lyricsThread) return;
        g_lyricsWantArtist = artist, g_lyricsWantTitle = title, g_lyricsWantAlbum = album;
        g_lyrics = nullptr;
        g_lyricsSerial.fetch_add(1);
    }
    if (!g_lyricsWake) g_lyricsWake = CreateEventW(nullptr, FALSE, FALSE, nullptr);
    if (!g_lyricsThread) {
        g_lyricsStop = false;
        g_lyricsThread = new std::thread(VizLyricsWorker);
    }
    SetEvent(g_lyricsWake);
}

void VizLyricsShutdown() {
    VizListenShutdown();
    if (!g_lyricsThread) return;
    g_lyricsStop = true;
    SetEvent(g_lyricsWake);
    if (g_lyricsThread->joinable()) g_lyricsThread->join();
    delete g_lyricsThread;
    g_lyricsThread = nullptr;
}

// Where the song is now, ms (with the offset), or -1 when the player doesn't say. Any thread.
int64_t VizLyricsPositionMs() {
    for (int tries = 0; tries < 64; tries++) {
        uint32_t s1 = g_tlSeq.load(std::memory_order_acquire);
        if (s1 & 1u) continue;
        bool valid = g_tlValid.load(std::memory_order_relaxed), running = g_tlRunning.load(std::memory_order_relaxed);
        int64_t start = g_tlStart.load(std::memory_order_relaxed);
        int64_t pos = g_tlPos.load(std::memory_order_relaxed);
        ULONGLONG tick = g_tlTick.load(std::memory_order_relaxed);
        std::atomic_thread_fence(std::memory_order_acquire);
        if (g_tlSeq.load(std::memory_order_relaxed) != s1) continue;
        if (!valid) return -1;
        double p = (double)(pos - start) / 10000.0;
        if (running) p += (double)(int64_t)(GetTickCount64() - tick);
        return (int64_t)p + (int64_t)g_settings.lyricsOffsetMs;
    }
    return -1;
}

// ---- Translate Lyrics: listening (machine translation, off) --------------------------------------------------------
// For a song whose timed lyrics have no translation from people or from a text model: what's sung is heard from the
// sound the Table already takes (nothing new is opened), and put into English by whisper.cpp (MIT, its whisper.dll
// and a ggml model in the Listening Models folder, loaded only when used), line by line against the lyrics' times.
// About ten seconds a time, every six, on a thread of its own with three cores at most; it waits on nothing while not
// wanted, and the drawing threads never wait on it. A line shows late or not at all rather than holding anything up.
#ifdef VIZ_HAVE_WHISPER
std::atomic<bool> g_listenWant{false};  // (the sound kept for listening: only while a song wants it)
std::mutex g_listenLock;
std::vector<float> g_listenRing;        // 16 kHz mono, the last 20 s
size_t g_listenHead = 0, g_listenHave = 0;
double g_listenAcc = 0, g_listenSum = 0;
int g_listenSumN = 0;
std::wstring g_listenKey;                // the song it's armed for
HANDLE g_listenWake = nullptr;
std::thread* g_listenThread = nullptr;
std::atomic<bool> g_listenStop{false};
constexpr size_t kListenRing = 16000 * 20;

// The capture thread's packets, made 16 kHz mono (each output the mean of the input it covers). Silence as zeros.
void VizListenTap(const float* f32, UINT32 frames, UINT32 ch, UINT32 rate) {
    if (!g_listenWant.load(std::memory_order_relaxed) || !rate || !ch) return;
    std::lock_guard<std::mutex> hold(g_listenLock);
    if (g_listenRing.size() != kListenRing) g_listenRing.assign(kListenRing, 0.f), g_listenHead = g_listenHave = 0;
    const double step = (double)rate / 16000.0;
    for (UINT32 i = 0; i < frames; i++) {
        float m = 0;
        if (f32)
            for (UINT32 c = 0; c < ch; c++) m += f32[(size_t)i * ch + c];
        g_listenSum += m / (float)ch, g_listenSumN++;
        if ((g_listenAcc += 1.0) >= step) {
            g_listenAcc -= step;
            g_listenRing[g_listenHead] = (float)(g_listenSum / std::max(1, g_listenSumN));
            g_listenHead = (g_listenHead + 1) % kListenRing;
            g_listenHave = std::min(kListenRing, g_listenHave + 1);
            g_listenSum = 0, g_listenSumN = 0;
        }
    }
}

// The listening models folder: the setting, else %LOCALAPPDATA%\Tourne\Table\Models\Listen.
std::wstring VizListenDir() {
    if (!g_settings.lyrListenModels.empty()) return g_settings.lyrListenModels;
    wchar_t p[MAX_PATH] = L"";
    return ExpandEnvironmentStringsW(L"%LOCALAPPDATA%\\Tourne\\Table\\Models\\Listen", p, MAX_PATH) ? p : L"";
}

struct VizWhisper {
    HMODULE lib = nullptr;
    decltype(&whisper_context_default_params_by_ref) ctxParams = nullptr;
    decltype(&whisper_init_from_file_with_params) init = nullptr;
    decltype(&whisper_full_default_params_by_ref) fullParams = nullptr;
    decltype(&whisper_full) full = nullptr;
    decltype(&whisper_full_n_segments) nSeg = nullptr;
    decltype(&whisper_full_get_segment_text) segText = nullptr;
    decltype(&whisper_full_get_segment_t0) segT0 = nullptr;
    decltype(&whisper_full_get_segment_t1) segT1 = nullptr;
    decltype(&whisper_full_lang_id) langId = nullptr;
    decltype(&whisper_lang_str) langStr = nullptr;
    decltype(&whisper_free) free = nullptr;
    decltype(&whisper_free_params) freeParams = nullptr;
    decltype(&whisper_log_set) logSet = nullptr;
    decltype(&whisper_free_context_params) freeCtxParams = nullptr;
    whisper_context* ctx = nullptr;
    ULONGLONG usedAt = 0;

    static void Quiet(enum ggml_log_level, const char*, void*) {}
    bool Load(std::wstring* why) {
        if (ctx) return true;
        const std::wstring dir = VizListenDir();
        if (!lib) {
            lib = LoadLibraryExW((dir + L"\\whisper.dll").c_str(), nullptr, LOAD_WITH_ALTERED_SEARCH_PATH);
            if (!lib) return *why = L"no whisper.dll in " + dir, false;
#define VIZ_WHISPER_FN(field, name) field = (decltype(field))(void*)GetProcAddress(lib, name)
            VIZ_WHISPER_FN(ctxParams, "whisper_context_default_params_by_ref");
            VIZ_WHISPER_FN(init, "whisper_init_from_file_with_params");
            VIZ_WHISPER_FN(fullParams, "whisper_full_default_params_by_ref");
            VIZ_WHISPER_FN(full, "whisper_full");
            VIZ_WHISPER_FN(nSeg, "whisper_full_n_segments");
            VIZ_WHISPER_FN(segText, "whisper_full_get_segment_text");
            VIZ_WHISPER_FN(segT0, "whisper_full_get_segment_t0");
            VIZ_WHISPER_FN(segT1, "whisper_full_get_segment_t1");
            VIZ_WHISPER_FN(langId, "whisper_full_lang_id");
            VIZ_WHISPER_FN(langStr, "whisper_lang_str");
            VIZ_WHISPER_FN(free, "whisper_free");
            VIZ_WHISPER_FN(freeParams, "whisper_free_params");
            VIZ_WHISPER_FN(logSet, "whisper_log_set");
            VIZ_WHISPER_FN(freeCtxParams, "whisper_free_context_params");
#undef VIZ_WHISPER_FN
            if (!ctxParams || !init || !fullParams || !full || !nSeg || !segText || !segT0 || !segT1 || !free || !freeParams)
                return *why = L"whisper.dll in " + dir + L" isn't a build this knows (1.7 or newer)", false;
            if (logSet) logSet(&VizWhisper::Quiet, nullptr);
        }
        // (the model: a many-language one before an English-only one, the smaller first)
        std::wstring model;
        uint64_t size = 0;
        bool multi = false;
        WIN32_FIND_DATAW fd;
        HANDLE h = FindFirstFileW((dir + L"\\ggml-*.bin").c_str(), &fd);
        if (h != INVALID_HANDLE_VALUE) {
            do {
                const uint64_t sz = ((uint64_t)fd.nFileSizeHigh << 32) | fd.nFileSizeLow;
                const bool m = !wcsstr(fd.cFileName, L".en");
                if (model.empty() || (m && !multi) || (m == multi && sz < size)) model = dir + L"\\" + fd.cFileName, size = sz, multi = m;
            } while (FindNextFileW(h, &fd));
            FindClose(h);
        }
        if (model.empty() || !multi) return *why = L"no many-language ggml model (ggml-small.bin or similar) in " + dir, false;
        whisper_context_params* cp = ctxParams();
        cp->use_gpu = false;
        char path[MAX_PATH * 3] = "";
        WideCharToMultiByte(CP_UTF8, 0, model.c_str(), -1, path, sizeof(path), nullptr, nullptr);
        ctx = init(path, *cp);
        if (freeCtxParams) freeCtxParams(cp);
        if (!ctx) return *why = L"the model in " + dir + L" can't be opened", false;
        return true;
    }
    void Unload() {
        if (ctx) free(ctx), ctx = nullptr;
    }
};

void VizListenWorker() {
    VizWhisper w;
    std::wstring key, heardLang;
    std::map<size_t, std::wstring> heard;  // (each lyric line's heard English)
    bool told = false;
    for (;;) {
        const bool armed = !g_listenKey.empty();
        WaitForSingleObject(g_listenWake, armed ? 6000 : (w.ctx ? 120000 : INFINITE));
        if (g_listenStop.load()) break;
        std::shared_ptr<const VizLyricSet> shown;
        std::wstring want;
        {
            std::lock_guard<std::mutex> lock(g_lyricsMutex);
            shown = g_lyrics;
        }
        {
            std::lock_guard<std::mutex> hold(g_listenLock);
            want = g_listenKey;
        }
        const bool on = g_settings.lyrTranslate && g_settings.lyrTransListen && shown && !want.empty() && shown->key == want && shown->synced &&
                        !shown->lines.empty() && (shown->trans.empty() || shown->transFrom.rfind(L"machine translation, heard", 0) == 0 ||
                                                     shown->transFrom == L"machine translation not available");
        if (!on) {
            g_listenWant.store(false);
            if (!want.empty() && (!shown || shown->key != want)) {
                std::lock_guard<std::mutex> hold(g_listenLock);
                g_listenKey.clear();
            }
            if (w.ctx && GetTickCount64() - w.usedAt > 120000) w.Unload();
            continue;
        }
        if (key != want) key = want, heard.clear(), heardLang.clear(), told = false;
        if (heardLang == L"en") continue;  // (sung in English: nothing to put into it)
        g_listenWant.store(true);
        std::vector<float> pcm;
        {
            std::lock_guard<std::mutex> hold(g_listenLock);
            const size_t n = std::min<size_t>(g_listenHave, 16000 * 10);
            if (n < 16000 * 6) continue;  // (six seconds heard at least)
            pcm.resize(n);
            for (size_t i = 0; i < n; i++) pcm[i] = g_listenRing[(g_listenHead + kListenRing - n + i) % kListenRing];
        }
        const int64_t end = VizLyricsPositionMs();
        if (end < 0) continue;
        std::wstring why;
        if (!w.Load(&why)) {
            if (!told) {
                Wh_Log(L"[Lyrics] listening: %s", why.c_str());
                told = true;
            }
            continue;
        }
        w.usedAt = GetTickCount64();
        whisper_full_params* p = w.fullParams(WHISPER_SAMPLING_GREEDY);
        p->n_threads = std::clamp((int)std::thread::hardware_concurrency() / 4, 1, 3);
        p->translate = true;
        p->language = "auto";
        p->no_context = true;
        p->print_progress = p->print_realtime = p->print_timestamps = p->print_special = false;
        p->suppress_blank = true;
        const ULONGLONG t0 = GetTickCount64();
        const int rc = w.full(w.ctx, *p, pcm.data(), (int)pcm.size());
        w.freeParams(p);
        if (rc != 0 || g_listenStop.load()) continue;
        if (w.langId && w.langStr) heardLang = VizUtf8ToWide(w.langStr(w.langId(w.ctx)));
        if (heardLang == L"en") {
            Wh_Log(L"[Lyrics] listening: sung in English, nothing to put into it");
            continue;
        }
        const int64_t start = end - (int64_t)pcm.size() / 16;
        std::map<size_t, std::wstring> got;
        for (int i = 0, n = w.nSeg(w.ctx); i < n; i++) {
            std::wstring text = VizUtf8ToWide(w.segText(w.ctx, i));
            size_t a = text.find_first_not_of(L' '), b = text.find_last_not_of(L' ');
            if (a == std::wstring::npos) continue;
            text = text.substr(a, b - a + 1);
            if (text.front() == L'[' || text.front() == L'(' || text.front() == L'♪') continue;  // ([Music], (singing), notes)
            const int64_t mid = start + (w.segT0(w.ctx, i) + w.segT1(w.ctx, i)) * 5;  // (centiseconds, the middle)
            size_t line = SIZE_MAX;
            for (size_t k = 0; k < shown->lines.size(); k++)
                if (shown->lines[k].ms <= mid && !shown->lines[k].text.empty()) line = k;
            if (line == SIZE_MAX) continue;
            std::wstring& g = got[line];
            g += (g.empty() ? L"" : L" ") + text;
        }
        // (a line heard whole in this window takes this hearing; one only partly in it keeps what it had)
        for (auto& kv : got) {
            const int64_t ls = shown->lines[kv.first].ms;
            if (ls >= start || !heard.count(kv.first)) heard[kv.first] = kv.second;
        }
        if (got.empty()) continue;
        auto withIt = std::make_shared<VizLyricSet>(*shown);
        withIt->trans.assign(shown->lines.size(), L"");
        for (auto& kv : heard) withIt->trans[kv.first] = kv.second;
        withIt->transFrom = L"machine translation, heard";
        {
            std::lock_guard<std::mutex> lock(g_lyricsMutex);
            if (g_lyrics != shown) continue;  // (moved on)
            g_lyrics = withIt;
            g_lyricsSerial.fetch_add(1);
        }
        Wh_Log(L"[Lyrics] listening: %zu lines heard (%s) in %llu ms", got.size(), heardLang.c_str(), GetTickCount64() - t0);
    }
    g_listenWant.store(false);
    w.Unload();
}

// Armed for a song with timed lyrics and no translation; the thread made on first use.
void VizListenArm(const std::wstring& key) {
    if (!g_settings.lyrTransListen) return;
    {
        std::lock_guard<std::mutex> hold(g_listenLock);
        g_listenKey = key;
        g_listenHave = 0;  // (the last song's sound isn't this one's)
    }
    if (!g_listenWake) g_listenWake = CreateEventW(nullptr, FALSE, FALSE, nullptr);
    if (!g_listenThread) g_listenStop = false, g_listenThread = new std::thread(VizListenWorker);
    SetEvent(g_listenWake);
}

void VizListenShutdown() {
    if (!g_listenThread) return;
    g_listenStop = true;
    SetEvent(g_listenWake);
    if (g_listenThread->joinable()) g_listenThread->join();
    delete g_listenThread;
    g_listenThread = nullptr;
}
#else
void VizListenArm(const std::wstring&) {}
void VizListenShutdown() {}
#endif  // VIZ_HAVE_WHISPER

// The line playing at ms: its index (-1 before the first), how far through it (0..1, to the next line's start) and
// the word playing in it (-1 for a file without word times).
struct VizLyricNow {
    int line = -1, word = -1;
    float along = 0.f;
};
VizLyricNow VizLyricsAt(const VizLyricSet& set, int64_t ms) {
    VizLyricNow n;
    if (!set.synced || set.lines.empty() || ms < 0) return n;
    auto it = std::upper_bound(set.lines.begin(), set.lines.end(), ms, [](int64_t t, auto const& l) { return t < l.ms; });
    n.line = (int)(it - set.lines.begin()) - 1;
    if (n.line < 0) return n;
    const auto& l = set.lines[n.line];
    int64_t end = n.line + 1 < (int)set.lines.size() ? set.lines[n.line + 1].ms : l.ms + 5000;
    n.along = end > l.ms ? std::clamp((float)(ms - l.ms) / (float)(end - l.ms), 0.f, 1.f) : 1.f;
    for (int w = 0; w < (int)l.words.size(); w++)
        if (l.words[w].first <= ms) n.word = w;
    return n;
}
HMODULE GetCurrentModuleHandle();
// ---- Lyrics, part 2: on screen, drawn by our own engine ------------------------------------------------------------
// A see-through window on the desktop (under your windows, like the Table's other parts) shows the playing line with
// the lines before and after it. How a line comes in, holds and leaves is an animation: a small text file of
// "key = value" lines (the built-in ones are below; Lyrics Animation File loads your own). Nothing is drawn, and the
// window is hidden, while Lyrics is off or the song has no timed lyrics.
struct VizLyricAnim {
    int unit = 1;                                         // 0 the line, 1 each word, 2 each letter
    float inMs = 420.f, inStagger = 45.f, outMs = 320.f;  // read in (each unit), its stagger, leave
    int inEase = 1, outEase = 1;                          // 0 linear, 1 out, 2 in-out, 3 back
    float inOpacity = 0.f, inX = 0.f, inY = 16.f, inScale = 1.f;     // where a unit comes in from
    float outOpacity = 0.f, outX = 0.f, outY = -12.f, outScale = 1.f;  // where the line goes
    float beatScale = 0.f, wave = 0.f, glow = 0.f;        // reacts: the beat, a wave through the words, a glow
    // Turning (degrees) and stretch (width and height apart) where a unit comes in from and where the line goes; and
    // in-between stops, as the icon animations have: "in.stop = at x y width height turn opacity" (at: per cent of
    // in.ms), likewise "out.stop". With stops, they say the whole way (the in. and out. keys above are left for them).
    // None of these set: everything as before.
    float inTurn = 0.f, inSx = 1.f, inSy = 1.f, outTurn = 0.f, outSx = 1.f, outSy = 1.f;
    struct Stop {
        float at = 0, x = 0, y = 0, sx = 1, sy = 1, turn = 0, opacity = 1;
    };
    std::vector<Stop> inStops, outStops;
    bool karaoke = true;                                  // sung words in the sung colour, the rest in the waiting one
    // karaoke.step: how a word lights, 0 sweeping through its letters (as always), 1 the whole word at once, 2 only the
    // word being sung (the rest wait). karaoke.colors: sung colours taking turns word by word (empty: the Lyrics
    // page's Sung colour). karaoke.base: the waiting colour while this animation is on (0: the Lyrics page's).
    int karaokeStep = 0;
    std::vector<uint32_t> karaokeColors;
    uint32_t karaokeBase = 0;
    // A letter effect from the living wallpapers (in place of the in. keys, letter by letter): 1 flip, 2 decode,
    // 3 drop, 4 ripple, 5 split, 6 type, 7 focus (Bonsai's message effects), 8 split-flap (Departures' board),
    // 9 prompt (Prompt's terminal, a slip now and then). 0 none. glyph.speed scales its time (2: twice as fast).
    int glyph = 0;
    float glyphSpeed = 1.f;
    // engine = web: the kept CSS ("#| " lines) run as written by the web engine (VizLyricsWebOn), the keys above the
    // stand-in wherever it can't run.
    bool web = false;
    std::wstring css;
    // A pen's markup ("#< " lines), the web engine's template: tpl.holder the element holding the lyric (child indexes
    // from the top, "0/1"), tpl.unit how (text: its text is the line; word or letter: a tag per one, made from its
    // first child), tpl.attrs the data-* attributes that hold the text too.
    std::wstring tpl, tplHolder, tplAttrs;
    int tplUnit = 0;
    // Its script ("#$ " lines) and libraries ("lib.N = <sha-256> <address>"), run only with Allow Scripts in My Own
    // Animations on, in Tourne Desktop's web engine.
    std::wstring script;
    std::vector<std::pair<std::wstring, std::wstring>> libs;
};
const wchar_t* const kVizLyricGlyphs[] = {L"none", L"flip", L"decode", L"bonsaidrop", L"ripple", L"split", L"type", L"focus", L"flap", L"prompt"};

// "key = value" lines; # starts a comment. Keys it doesn't know are left (so a newer file still loads).
uint32_t VizLyricArgb(const std::wstring& s, uint32_t fallback);
// Where a line's comment starts: the first # that isn't a colour (#rrggbb or #rrggbbaa, then the end, a space or a
// comma), so karaoke.colors = #3060FF, #FF3040 keeps its colours. npos: no comment.
size_t VizLyricCommentAt(const std::wstring& line) {
    for (size_t h = line.find(L'#'); h != std::wstring::npos; h = line.find(L'#', h + 1)) {
        size_t n = 0;
        while (h + 1 + n < line.size() && iswxdigit(line[h + 1 + n])) n++;
        const size_t after = h + 1 + n;
        const bool colour = (n == 6 || n == 8) && (after == line.size() || iswspace(line[after]) || line[after] == L',');
        if (!colour) return h;
    }
    return std::wstring::npos;
}
// A CSS colour as 0xAARRGGBB: #rgb, #rrggbb, #rrggbbaa, rgb()/rgba(), or a common name. 0: not read.
uint32_t VizCssColour(std::wstring v) {
    std::wstring low;
    for (wchar_t c : v)
        if (!iswspace(c)) low += (wchar_t)towlower(c);
    static const struct { const wchar_t* n; uint32_t c; } kNames[] = {
        {L"black", 0xFF000000}, {L"white", 0xFFFFFFFF}, {L"red", 0xFFFF0000}, {L"blue", 0xFF0000FF}, {L"yellow", 0xFFFFFF00},
        {L"green", 0xFF008000}, {L"lime", 0xFF00FF00}, {L"orange", 0xFFFFA500}, {L"purple", 0xFF800080}, {L"pink", 0xFFFFC0CB},
        {L"cyan", 0xFF00FFFF}, {L"aqua", 0xFF00FFFF}, {L"magenta", 0xFFFF00FF}, {L"fuchsia", 0xFFFF00FF}, {L"gray", 0xFF808080},
        {L"grey", 0xFF808080}, {L"gold", 0xFFFFD700}, {L"teal", 0xFF008080}, {L"navy", 0xFF000080}, {L"violet", 0xFFEE82EE},
    };
    for (const auto& n : kNames)
        if (low == n.n) return n.c;
    if (!low.empty() && low[0] == L'#') {
        std::wstring h = low.substr(1);
        if (h.size() == 3 || h.size() == 4) {
            std::wstring x;
            for (wchar_t c : h) x += c, x += c;
            h = x;
        }
        if (h.size() != 6 && h.size() != 8) return 0;
        for (wchar_t c : h)
            if (!iswxdigit(c)) return 0;
        const uint32_t n = (uint32_t)wcstoul(h.c_str(), nullptr, 16);
        return h.size() == 6 ? 0xFF000000u | n : (n >> 8) | ((n & 255) << 24);  // (CSS #rrggbbaa: alpha last)
    }
    if (low.rfind(L"rgb", 0) == 0) {
        size_t a = low.find(L'('), b = low.find(L')');
        if (a == std::wstring::npos || b == std::wstring::npos) return 0;
        float c[4] = {0, 0, 0, 1};
        int n = 0;
        for (size_t at = a + 1; at < b && n < 4;) {
            size_t e = low.find_first_of(L",/)", at);
            if (e == std::wstring::npos || e > b) e = b;
            std::wstring part = low.substr(at, e - at);
            if (!part.empty()) {
                float f = (float)_wtof(part.c_str());
                if (part.back() == L'%') f = n < 3 ? f * 2.55f : f / 100.f;
                c[n++] = f;
            }
            at = e + 1;
        }
        if (n < 3) return 0;
        auto ch = [](float f) { return (uint32_t)std::clamp((int)std::lround(f), 0, 255); };
        return ch(c[3] * 255.f) << 24 | ch(c[0]) << 16 | ch(c[1]) << 8 | ch(c[2]);
    }
    return 0;
}

void VizParseLyricAnim(const std::wstring& text, VizLyricAnim* a) {
    size_t at = 0;
    while (at < text.size()) {
        size_t nl = text.find(L'\n', at);
        std::wstring line = text.substr(at, nl == std::wstring::npos ? std::wstring::npos : nl - at);
        at = nl == std::wstring::npos ? text.size() : nl + 1;
        if (line.rfind(L"#| ", 0) == 0) {
            a->css += line.substr(3) + L"\n";
            continue;
        }
        if (line == L"#|") {
            a->css += L"\n";
            continue;
        }
        if (line.rfind(L"#< ", 0) == 0) {
            a->tpl += line.substr(3) + L"\n";
            continue;
        }
        if (line.rfind(L"#$ ", 0) == 0 || line == L"#$") {
            a->script += (line.size() > 3 ? line.substr(3) : L"") + L"\n";
            continue;
        }
        if (size_t hash = VizLyricCommentAt(line); hash != std::wstring::npos) line.resize(hash);
        size_t eq = line.find(L'=');
        if (eq == std::wstring::npos) continue;
        std::wstring k = line.substr(0, eq), v = line.substr(eq + 1);
        auto trim = [](std::wstring& s) {
            while (!s.empty() && iswspace(s.front())) s.erase(s.begin());
            while (!s.empty() && iswspace(s.back())) s.pop_back();
        };
        trim(k), trim(v);
        k = VizLyricsLower(k);
        const float f = (float)_wtof(v.c_str());
        auto ease = [&](int* e) {
            std::wstring l = VizLyricsLower(v);
            *e = l == L"linear" ? 0 : l == L"inout" ? 2 : l == L"back" ? 3 : 1;
        };
        if (k == L"unit") a->unit = VizLyricsLower(v) == L"line" ? 0 : VizLyricsLower(v) == L"letter" ? 2 : 1;
        else if (k == L"in.ms") a->inMs = std::clamp(f, 1.f, 5000.f);
        else if (k == L"in.stagger") a->inStagger = std::clamp(f, 0.f, 2000.f);
        else if (k == L"in.ease") ease(&a->inEase);
        else if (k == L"in.opacity") a->inOpacity = std::clamp(f, 0.f, 1.f);
        else if (k == L"in.x") a->inX = f;
        else if (k == L"in.y") a->inY = f;
        else if (k == L"in.scale") a->inScale = std::clamp(f, 0.f, 10.f);
        else if (k == L"out.ms") a->outMs = std::clamp(f, 1.f, 5000.f);
        else if (k == L"out.ease") ease(&a->outEase);
        else if (k == L"out.opacity") a->outOpacity = std::clamp(f, 0.f, 1.f);
        else if (k == L"out.x") a->outX = f;
        else if (k == L"out.y") a->outY = f;
        else if (k == L"out.scale") a->outScale = std::clamp(f, 0.f, 10.f);
        else if (k == L"in.turn") a->inTurn = std::clamp(f, -3600.f, 3600.f);
        else if (k == L"in.sx") a->inSx = std::clamp(f, -10.f, 10.f);
        else if (k == L"in.sy") a->inSy = std::clamp(f, -10.f, 10.f);
        else if (k == L"out.turn") a->outTurn = std::clamp(f, -3600.f, 3600.f);
        else if (k == L"out.sx") a->outSx = std::clamp(f, -10.f, 10.f);
        else if (k == L"out.sy") a->outSy = std::clamp(f, -10.f, 10.f);
        else if ((k == L"in.stop" || k == L"out.stop") && (k[0] == L'i' ? a->inStops : a->outStops).size() < 32) {
            auto& list = k[0] == L'i' ? a->inStops : a->outStops;
            VizLyricAnim::Stop st = list.empty() ? VizLyricAnim::Stop{} : list.back();
            float* fs[] = {&st.at, &st.x, &st.y, &st.sx, &st.sy, &st.turn, &st.opacity};
            const wchar_t* pc = v.c_str();
            for (int i = 0; i < 7 && *pc; i++) {
                wchar_t* end = nullptr;
                const float n = wcstof(pc, &end);
                if (end == pc) break;
                *fs[i] = n;
                pc = end;
            }
            st.at = std::clamp(st.at, list.empty() ? 0.f : list.back().at, 100.f), st.opacity = std::clamp(st.opacity, 0.f, 1.f);
            st.sx = std::clamp(st.sx, -10.f, 10.f), st.sy = std::clamp(st.sy, -10.f, 10.f), st.x = std::clamp(st.x, -2000.f, 2000.f), st.y = std::clamp(st.y, -2000.f, 2000.f);
            list.push_back(st);
        }
        else if (k == L"react.beat") a->beatScale = std::clamp(f, 0.f, 1.f);
        else if (k == L"react.wave") a->wave = std::clamp(f, 0.f, 100.f);
        else if (k == L"glow") a->glow = std::clamp(f, 0.f, 1.f);
        else if (k == L"karaoke") a->karaoke = f != 0.f || VizLyricsLower(v) == L"on" || VizLyricsLower(v) == L"true";
        else if (k == L"karaoke.step") {
            const std::wstring w = VizLyricsLower(v);
            a->karaokeStep = w == L"word" ? 1 : w == L"current" ? 2 : 0;
        } else if (k == L"karaoke.colors" || k == L"karaoke.colours") {
            a->karaokeColors.clear();
            for (size_t at = 0; at <= v.size() && a->karaokeColors.size() < 12;) {
                size_t e = v.find(L',', at);
                if (e == std::wstring::npos) e = v.size();
                if (const uint32_t c = VizCssColour(v.substr(at, e - at))) a->karaokeColors.push_back(c);
                at = e + 1;
            }
        } else if (k == L"karaoke.base") a->karaokeBase = VizCssColour(v);
        else if (k == L"glyph") {
            a->glyph = 0;
            for (int i = 0; i < (int)ARRAYSIZE(kVizLyricGlyphs); i++)
                if (VizLyricsLower(v) == kVizLyricGlyphs[i]) a->glyph = i;
        } else if (k == L"glyph.speed") a->glyphSpeed = std::clamp(f, 0.1f, 10.f);
        else if (k == L"engine") a->web = VizLyricsLower(v) == L"web";
        else if (k == L"tpl.holder") a->tplHolder = v.substr(0, 80);
        else if (k == L"tpl.unit") a->tplUnit = VizLyricsLower(v) == L"letter" ? 2 : VizLyricsLower(v) == L"word" ? 1 : 0;
        else if (k == L"tpl.attrs") a->tplAttrs = v.substr(0, 200);
        else if (k.rfind(L"lib.", 0) == 0 && a->libs.size() < 8) {
            size_t sp = v.find(L' ');
            std::wstring sha = VizLyricsLower(v.substr(0, sp)), url = sp == std::wstring::npos ? L"" : v.substr(sp + 1);
            bool hex = sha.size() == 64;
            for (wchar_t c : sha) hex = hex && iswxdigit(c);
            if (hex) a->libs.push_back({sha, url});
        }
    }
}

float VizLyricEase(int e, float t);
// Where stops put a unit at `t` (0 to 1 of the time), each stretch between two eased by `ease`.
VizLyricAnim::Stop VizLyricStopAt(const std::vector<VizLyricAnim::Stop>& stops, int ease, float t) {
    if (stops.empty()) return {};
    if (stops.size() == 1) return stops[0];
    const float pc = std::clamp(t, 0.f, 1.f) * 100.f;
    size_t i = 0;
    while (i + 2 < stops.size() && pc > stops[i + 1].at) i++;
    const auto &p = stops[i], &q = stops[i + 1];
    const float span = q.at - p.at;
    const float u = VizLyricEase(ease, span > 0 ? std::clamp((pc - p.at) / span, 0.f, 1.f) : 1.f);
    auto mix = [&](float a, float b) { return a + (b - a) * u; };
    VizLyricAnim::Stop s;
    s.x = mix(p.x, q.x), s.y = mix(p.y, q.y), s.sx = mix(p.sx, q.sx), s.sy = mix(p.sy, q.sy), s.turn = mix(p.turn, q.turn), s.opacity = mix(p.opacity, q.opacity);
    return s;
}

// The built-in animations, in the same format as a file of your own.
const wchar_t* VizLyricBuiltin(const std::wstring& name) {
    if (name == L"fade") return L"unit = line\nin.ms = 350\nin.y = 0\nout.ms = 300\nout.y = 0\n";
    if (name == L"typewriter") return L"unit = letter\nin.ms = 1\nin.stagger = 35\nin.y = 0\nout.ms = 250\nout.y = 0\n";
    if (name == L"karaoke") return L"unit = word\nin.ms = 200\nin.stagger = 0\nin.y = 0\nout.ms = 200\nout.y = 0\nkaraoke = on\nglow = 0.4\n";
    // The living wallpapers' letter effects.
    for (int i = 1; i < (int)ARRAYSIZE(kVizLyricGlyphs); i++)
        if (VizLyricsLower(name) == kVizLyricGlyphs[i]) {
            static std::wstring s_text[ARRAYSIZE(kVizLyricGlyphs)];
            s_text[i] = std::wstring(L"unit = letter\nout.ms = 260\nout.y = 0\nglyph = ") + kVizLyricGlyphs[i] + L"\n";
            return s_text[i].c_str();
        }
    if (name == L"wave") return L"unit = word\nin.ms = 500\nin.stagger = 60\nin.y = 10\nreact.wave = 4\nout.ms = 300\nout.y = -8\n";
    if (name == L"drop") return L"unit = letter\nin.ms = 380\nin.stagger = 18\nin.y = -26\nin.ease = back\nout.ms = 300\nout.y = 18\n";
    return L"unit = word\nin.ms = 420\nin.stagger = 45\nin.y = 16\nout.ms = 320\nout.y = -12\nreact.beat = 0.04\n";  // rise
}

float VizLyricEase(int e, float t) {
    t = std::clamp(t, 0.f, 1.f);
    if (e == 0) return t;
    if (e == 2) return t < 0.5f ? 2.f * t * t : 1.f - powf(-2.f * t + 2.f, 2.f) / 2.f;
    if (e == 3) {
        const float c1 = 1.70158f, c3 = c1 + 1.f;
        return 1.f + c3 * powf(t - 1.f, 3.f) + c1 * powf(t - 1.f, 2.f);
    }
    return 1.f - (1.f - t) * (1.f - t) * (1.f - t);
}

// The living wallpapers' letter effects (Tourne Desktop's Bonsai message, Departures board and Prompt terminal),
// timed as they are there, for one line t seconds after it came in. put(char index, glyph shown, rise in half
// lines, tint: 0 its own colour, 1 the waiting colour (decode's settling glyphs), 2 red, 3 green (split's copies),
// shift in letter widths). A letter not yet in is not put.
float VizLyricHash01(uint64_t x) {
    x ^= x >> 33, x *= 0xff51afd7ed558ccdULL, x ^= x >> 33, x *= 0xc4ceb9fe1a85ec53ULL, x ^= x >> 33;
    return (float)((x >> 11) * (1.0 / 9007199254740992.0));
}
template <class Put>
void VizLyricGlyphLine(const std::wstring& s, int lineIndex, double tt, int effect, Put put) {
    const int n = (int)s.size();
    if (!n) return;
    // Bonsai sweeps a word's timings over a longer message, the last letter starting within 24 steps.
    const double squeeze = std::min(1.0, 24.0 / std::max(1, n - 1)), perType = std::min(0.055, 2.0 / std::max(1, n));
    static const wchar_t kRain[] = L"0123456789ABCDEF:=+*<>#%&";
    static const wchar_t kFlaps[] = L" ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789%:-./";
    const int nFlaps = (int)wcslen(kFlaps);
    if (effect == 9) {
        // Prompt: typed at 38 keys a second behind a block cursor; every third line slips (two letters swapped,
        // a pause, two rub-outs) as the wallpaper's command does.
        std::vector<std::wstring> keys;
        if (lineIndex % 3 != 1 || n < 11) {
            for (int i = 0; i <= n; i++) keys.push_back(s.substr(0, i));
        } else {
            for (int i = 0; i <= 9; i++) keys.push_back(s.substr(0, i));
            keys.push_back(s.substr(0, 9) + s[10]);
            keys.push_back(s.substr(0, 9) + s[10] + s[9]);
            for (int i = 0; i < 13; i++) keys.push_back(keys.back());
            keys.push_back(s.substr(0, 9) + s[10]);
            keys.push_back(s.substr(0, 9));
            for (int i = 10; i <= n; i++) keys.push_back(s.substr(0, i));
        }
        const size_t k = std::min(keys.size() - 1, (size_t)std::max(0.0, std::round(tt * 38)));
        const std::wstring& shown = keys[k];
        for (int c = 0; c < (int)shown.size(); c++)
            if (shown[c] != L' ') put(c, shown[c], 0.f, 0, 0.f);
        if (k + 1 < keys.size() || fmod(tt, 1.1) < 0.55) put((int)shown.size() < n ? (int)shown.size() : n - 1, L'█', 0.f, 1,
                                                            (int)shown.size() < n ? 0.f : 1.f);
        return;
    }
    for (int c = 0; c < n; c++) {
        wchar_t ch = s[c];
        if (ch == L' ') continue;
        float dy = 0.f;
        int tint = 0;
        const double turn = c * squeeze;
        switch (effect) {
            case 1: {  // flip: turning over, 35 ms apart
                double a = tt - turn * 0.035;
                if (a < 0) continue;
                if (a < 0.035) ch = L'-';
                else if (a < 0.07) ch = L'|';
                break;
            }
            case 2: {  // decode: random glyphs settle, letter i locking at frame 2i+3 (40 ms frames)
                int fr = (int)(tt / 0.04);
                if (fr < (int)(2 * turn) + 3) ch = kRain[(size_t)(VizLyricHash01((uint64_t)fr * 7919 + (uint64_t)c * 104729) * 25)], tint = 1;
                break;
            }
            case 3: {  // drop: falling in 40 ms apart, a slight overshoot
                double a = tt - turn * 0.04;
                if (a < 0) continue;
                static const float kFall[] = {-3, -2, -1, 1, 0};
                int step = (int)(a / 0.03);
                if (step < 5) dy = kFall[step];
                break;
            }
            case 4: {  // ripple: a ripple running through once, 45 ms apart
                double a = tt - turn * 0.045;
                if (a >= 0 && a < 0.09) dy = -1;
                break;
            }
            case 5: {  // split: red and green copies slide apart, then lock
                int apart = (int)std::lround(3 * (1 - std::clamp(tt / 0.4, 0.0, 1.0)) * (tt < 0.15 ? tt / 0.15 : 1));
                if (apart > 0) {
                    put(c, ch, 0.f, 2, (float)-apart), put(c, ch, 0.f, 3, (float)apart);
                    continue;
                }
                break;
            }
            case 6: {  // type: 55 ms a letter (2 s at most), a block cursor ahead
                int typed = (int)(tt / perType);
                if (c > typed) continue;
                if (c == typed && typed < n) ch = L'█';
                break;
            }
            case 7: {  // focus: sharpening, centre out, 50 ms apart
                double rank = std::abs(c - (n - 1) / 2.0) * std::min(1.0, 12.0 / std::max(1.0, n / 2.0 + 1));
                double a = tt - rank * 0.05;
                if (a < 0) ch = L'░';
                else if (a < 0.05) ch = L'▒';
                break;
            }
            case 8: {  // split-flap: each letter riffles from blank to itself, 30 ms apart, as the board's flaps
                const wchar_t* p = wcschr(kFlaps, towupper(ch));
                int to = p ? (int)(p - kFlaps) : -1, travel = to >= 0 ? to : nFlaps / 2, flips = travel;
                while (flips < 7) flips += nFlaps;
                double start = c * 0.03, dur = std::clamp(flips / 14.0, 0.5, 1.4);
                if (tt < start) continue;
                if (tt < start + dur) {
                    wchar_t f = kFlaps[(int)std::floor((tt - start) / dur * flips) % nFlaps];
                    if (f == L' ') continue;
                    ch = f;
                }
                break;
            }
        }
        put(c, ch, dy, tint, 0.f);
    }
}

// Instrumental Disperse: Tourne Desktop's window close effects (slipstream-close.cpp: Wake, Derez, Shatter, Melt,
// Dust; Motion as windowsOut's fade and shrink), their motion and timing copied for letters, since the Table stands
// alone. t: seconds into the effect at its own pace. (cx, cy): the letter's middle in the lines' box (w x h); cell:
// a letter's size; seed: one per letter. Out: where it is, how big, turned, how solid, how far toward the ink colour,
// and the glyph to show (0: its own).
struct VizLyricGone {
    float dx = 0, dy = 0, sx = 1, sy = 1, turn = 0, alpha = 1, ink = 0;
    wchar_t glyph = 0;
};
float VizLyricDisperseSeconds(int effect) { return effect == 3 ? 1.1f : effect == 4 ? 0.9f : effect == 5 ? 1.0f : effect == 1 ? 0.95f : effect == 2 ? 1.1f : 0.35f; }
VizLyricGone VizLyricDisperse(int effect, float t, float cx, float cy, float w, float h, float cell, uint64_t seed) {
    VizLyricGone o;
    auto hash = [&](uint64_t k) { return VizLyricHash01(seed * 1000003ull + k); };
    auto sat = [](float v) { return std::clamp(v, 0.f, 1.f); };
    switch (effect) {
        case 3: {  // Shatter: cracks from the middle, then each piece drops on its own beat, drifting and turning
            const float mx = w * 0.5f, my = h * 0.5f, reach = sqrtf(mx * mx + my * my) + 1.f;
            const float delay = 0.12f + 0.28f * sqrtf((cx - mx) * (cx - mx) + (cy - my) * (cy - my)) / reach + 0.06f * hash(1);
            const float tau = std::max(t - delay, 0.f), g = 2.f * (h * 1.5f) / (0.75f * 0.75f);
            o.dx = (hash(7) - 0.5f) * cell * 1.2f * tau;
            o.dy = 0.5f * g * tau * tau;
            o.turn = (hash(3) - 0.5f) * 1.6f * tau;
            o.ink = (t >= delay - 0.12f ? 1.f : 0.f) * (0.35f + 0.65f * (1.f - sat(tau / 0.35f)));
            o.alpha = 1.f - sat((tau - 0.35f) / 0.3f);
            break;
        }
        case 4: {  // Melt: each letter lets go on its own beat and runs down, stretching, its top lit
            const float n = hash(11), drip = hash(12);
            const float delay = n * 0.26f + (1.f - drip * drip) * 0.12f, u = sat((t - delay) / 0.6f);
            o.dy = u * u * h * 0.6f;
            o.sy = 1.f + 0.8f * u;
            o.ink = u > 0.f ? 0.9f * (1.f - u) : 0.f;
            const float s = sat((u - 0.55f) / 0.45f);
            o.alpha = 1.f - s * s * (3.f - 2.f * s);
            break;
        }
        case 5: {  // Dust: a sweep from the left lets the letters go as specks drifting up and away
            const float rel = (cx / std::max(w, 1.f)) * 0.55f + 0.12f * hash(21), tau = t - rel;
            if (tau <= 0.f) break;
            const float len = sqrtf(1.f + 0.55f * 0.55f), speed = (200.f + 220.f * hash(25)) * cell / 20.f;
            o.dx = speed * tau / len;
            o.dy = -0.55f * speed * tau / len + (hash(26) - 0.5f) * 0.9f * cell * sinf(tau * 6.f);
            o.sx = o.sy = 1.f - 0.6f * sat(tau / 0.55f);
            o.ink = sat(tau / 0.3f) * 0.7f;
            o.alpha = 1.f - sat(tau / 0.55f);
            break;
        }
        case 1: {  // Wake: the lines hold a moment, then drop as one pane, eaten from the top along a glowing edge
            const float fall = std::max(0.f, t - 0.15f);
            o.dy = 0.5f * (h * 3.f) * fall * fall;
            const float edge = (t / 0.8f) * (h + cell * 2.f) - cell + (hash(31) - 0.5f) * cell * 0.6f;  // (ragged)
            const float d = cy - edge;
            o.alpha = d < 0.f ? 0.f : 1.f;
            o.ink = d >= 0.f ? 1.f - sat(d / (cell * 1.2f)) : 0.f;
            break;
        }
        case 2: {  // Derez: read out from the top into falling code
            static const wchar_t kRain[] = L"0123456789ABCDEF:=+*<>#%&";
            const float delay = sat(cy / std::max(h, 1.f)) * 0.45f + 0.08f * hash(41);
            const float tau = t - delay;
            if (tau <= 0.f) break;
            o.glyph = kRain[(size_t)(VizLyricHash01(seed * 31ull + (uint64_t)(tau / 0.05f)) * 25)];
            o.ink = 1.f;
            o.dy = tau * tau * h * 2.2f;
            o.alpha = 1.f - sat((tau - 0.25f) / 0.4f);
            break;
        }
        default: {  // Motion: as windowsOut's fade, a little smaller as it goes
            const float e = VizLyricEase(1, t / 0.35f);
            o.sx = o.sy = 1.f - 0.08f * e;
            o.alpha = 1.f - e;
            break;
        }
    }
    return o;
}

