// The made-up song the editor plays (invented lines, never a real song's), looping on the clock: some lines with
// word times, an empty one between verses.
std::shared_ptr<const VizLyricSet> VizLyricsPlaceholder() {
    static std::shared_ptr<VizLyricSet> s;
    if (!s) {
        s = std::make_shared<VizLyricSet>();
        s->key = L"\npreview";
        s->synced = true;
        const struct { int ms; const wchar_t* text; bool words; } lines[] = {
            {0, L"Here comes a line that nobody wrote", true},
            {3400, L"Every word arrives in its own time", false},
            {6600, L"Holding on and on and on", true},
            {10200, L"Then quick words tumble out together", false},
            {13000, L"", false},
            {15600, L"And round again to start the song", true},
        };
        for (const auto& l : lines) {
            VizLyricLine line;
            line.ms = l.ms, line.text = l.text;
            if (l.words) {
                int64_t t = l.ms;
                for (size_t i = 0; i < line.text.size();) {
                    size_t j = line.text.find(L' ', i);
                    if (j == std::wstring::npos) j = line.text.size();
                    line.words.push_back({t, (int)i});
                    t += 180 + 70 * (int64_t)(j - i);
                    i = j + 1;
                }
            }
            s->lines.push_back(line);
        }
    }
    return s;
}
