// ---- Lyrics, the web engine ------------------------------------------------------------------------------------------
// An animation file with "engine = web" runs its kept CSS (the "#| " lines) as written, in Microsoft Edge's WebView2,
// instead of our engine's keys. Only where Tourne Desktop is built with WebView2's header (third_party/webview2);
// elsewhere, and whenever the web engine can't start, the file's own keys draw it as before.
// - Nothing of Edge runs unless a web animation is on screen: its thread, window and browser start with the first
//   web frame, and end a few seconds after the last.
// - No scripts but ours and nothing online: the page's Content-Security-Policy allows only our one script (by nonce)
//   and inline styles; every request it might make is answered "blocked" before it leaves; no new windows, no other
//   page, no dev tools, menus, zoom or dialogs. The animation's CSS goes in as a style's text, never as markup.
// - It sits where the lyrics window would (that window hidden meanwhile), click-through, never taking focus, kept
//   out of nothing (the lyrics are meant to be seen and recorded).
#if 0  // (WebView2's SDK header: not in Windhawk)
#include "third_party/webview2/WebView2.h"
#define VIZ_LYRICS_WEB 1
#endif

struct VizLyrWebFrame {
    bool show = false;
    RECT rc{};            // screen pixels
    HWND above = nullptr;  // the window it sits just above (the lyrics' parent's top window), or null for its own place
    bool topmost = false;
    std::wstring state;   // the page's state as JSON, without the song time
    int64_t songMs = 0;
    bool scripted = false;   // its scripts allowed and present: the locked run
    std::wstring scripts;    // (then) what the page loads, as JSON
};

// The CSS kept in an animation, and its animation declarations: those of the first rule (not a @keyframes) that has
// any, as written ("animation: x 0.6s ease both" and its longhands), put on each unit by the page.
std::wstring VizLyrWebAnimDecls(const std::wstring& css) {
    size_t at = 0;
    while (at < css.size()) {
        size_t open = css.find(L'{', at);
        if (open == std::wstring::npos) break;
        std::wstring head = css.substr(at, open - at);
        // The block's end, nested braces counted.
        int depth = 1;
        size_t close = open + 1;
        for (; close < css.size() && depth; close++) depth += css[close] == L'{' ? 1 : css[close] == L'}' ? -1 : 0;
        std::wstring lowHead = VizLyricsLower(head);
        if (lowHead.find(L"@keyframes") == std::wstring::npos && lowHead.find(L"@-webkit-keyframes") == std::wstring::npos &&
            lowHead.find(L'@') == std::wstring::npos) {
            std::wstring body = css.substr(open + 1, close - open - 2), out;
            size_t d = 0;
            while (d < body.size()) {
                size_t semi = body.find(L';', d);
                std::wstring decl = body.substr(d, semi == std::wstring::npos ? std::wstring::npos : semi - d);
                d = semi == std::wstring::npos ? body.size() : semi + 1;
                size_t s = decl.find_first_not_of(L" \t\r\n");
                if (s == std::wstring::npos) continue;
                decl = decl.substr(s);
                std::wstring low = VizLyricsLower(decl);
                if (low.rfind(L"animation", 0) == 0 || low.rfind(L"-webkit-animation", 0) == 0) out += decl + L";";
            }
            if (!out.empty()) return out;
        }
        at = close;
    }
    return L"";
}

// The CSS as the page takes it: lines that could reach out (url(), @import, expression(), javascript:) left out
// (the page's policy would refuse them anyway).
std::wstring VizLyrWebCleanCss(const std::wstring& css) {
    std::wstring out;
    size_t at = 0;
    while (at < css.size()) {
        size_t nl = css.find(L'\n', at);
        std::wstring line = css.substr(at, nl == std::wstring::npos ? std::wstring::npos : nl - at);
        at = nl == std::wstring::npos ? css.size() : nl + 1;
        std::wstring low = VizLyricsLower(line);
        if (low.find(L"url(") != std::wstring::npos || low.find(L"@import") != std::wstring::npos || low.find(L"expression(") != std::wstring::npos ||
            low.find(L"javascript:") != std::wstring::npos || low.find(L"</") != std::wstring::npos)
            continue;
        out += line + L"\n";
    }
    return out;
}

std::wstring LeUtf8(const std::string& s) {
    size_t skip = s.size() >= 3 && (unsigned char)s[0] == 0xEF && (unsigned char)s[1] == 0xBB && (unsigned char)s[2] == 0xBF ? 3 : 0;
    int n = MultiByteToWideChar(CP_UTF8, 0, s.data() + skip, (int)(s.size() - skip), nullptr, 0);
    std::wstring w(n, L'\0');
    MultiByteToWideChar(CP_UTF8, 0, s.data() + skip, (int)(s.size() - skip), w.data(), n);
    w.erase(std::remove(w.begin(), w.end(), L'\r'), w.end());
    return w;
}

// ---- The pen's markup as a template ----
struct LeTplEl {
    std::wstring tag, cls, id, text, style, path;
    std::vector<std::pair<std::wstring, std::wstring>> data;  // its data-* attributes
    int parent = -1;
    std::vector<int> kids;
};

// The markup kept: the structure the CSS hooks into (allowed elements with class, id, data-*, aria-*, role and a
// plain style), the rest taken out. `dropped`: how many parts went.
std::wstring LeCleanHtml(const std::wstring& src, std::vector<LeTplEl>* els, bool* hadScript, int* dropped) {
    static const wchar_t* kKeep[] = {L"div", L"span", L"p", L"h1", L"h2", L"h3", L"h4", L"h5", L"h6", L"section", L"article", L"header", L"footer",
                                     L"main", L"ul", L"ol", L"li", L"em", L"strong", L"b", L"i", L"u", L"small", L"sup", L"sub", L"br", L"hr",
                                     L"blockquote", L"figure", L"figcaption", L"mark", L"code", L"pre", L"q", L"s", L"del", L"ins", L"abbr", L"time", L"label"};
    static const wchar_t* kDropAll[] = {L"script", L"style", L"noscript", L"template", L"iframe", L"frame", L"frameset", L"object", L"embed", L"applet",
                                        L"svg", L"math", L"canvas", L"video", L"audio", L"picture", L"form", L"select", L"textarea", L"button",
                                        L"head", L"title", L"map", L"portal", L"dialog"};
    static const wchar_t* kVoid[] = {L"br", L"hr", L"img", L"input", L"meta", L"link", L"source", L"track", L"wbr", L"area", L"base", L"col", L"param", L"embed"};
    auto in = [](const wchar_t* const* list, size_t n, const std::wstring& t) {
        for (size_t i = 0; i < n; i++)
            if (t == list[i]) return true;
        return false;
    };
    // (only the body's inside, when it's a whole page)
    std::wstring s = src, low = VizLyricsLower(src);
    if (size_t b = low.find(L"<body"); b != std::wstring::npos) {
        size_t open = low.find(L'>', b);
        size_t end = low.rfind(L"</body");
        if (open != std::wstring::npos) s = src.substr(open + 1, end == std::wstring::npos || end < open ? std::wstring::npos : end - open - 1);
    }
    low = VizLyricsLower(s);
    std::wstring out;
    struct Open { std::wstring tag; int el; };
    std::vector<Open> stack;
    auto topEl = [&]() {
        for (size_t k = stack.size(); k-- > 0;)
            if (stack[k].el >= 0) return stack[k].el;
        return -1;
    };
    size_t i = 0;
    while (i < s.size()) {
        if (s[i] != L'<') {
            size_t e = s.find(L'<', i);
            std::wstring t = s.substr(i, e == std::wstring::npos ? std::wstring::npos : e - i);
            out += t;
            if (int el = topEl(); el >= 0) {
                std::wstring tt = t;
                while (!tt.empty() && iswspace(tt.front())) tt.erase(tt.begin());
                while (!tt.empty() && iswspace(tt.back())) tt.pop_back();
                (*els)[el].text += tt;
            }
            i = e == std::wstring::npos ? s.size() : e;
            continue;
        }
        if (low.compare(i, 4, L"<!--") == 0) {
            size_t e = low.find(L"-->", i + 4);
            i = e == std::wstring::npos ? s.size() : e + 3;
            continue;
        }
        if (i + 1 < s.size() && (s[i + 1] == L'!' || s[i + 1] == L'?')) {
            size_t e = s.find(L'>', i);
            i = e == std::wstring::npos ? s.size() : e + 1;
            continue;
        }
        const bool closing = i + 1 < s.size() && s[i + 1] == L'/';
        size_t p = i + (closing ? 2 : 1), ns = p;
        while (p < s.size() && (iswalnum(s[p]) || s[p] == L'-')) p++;
        std::wstring tag = low.substr(ns, p - ns);
        // (to the tag's end, quotes minded)
        std::vector<std::pair<std::wstring, std::wstring>> attrs;
        bool selfClose = false;
        while (p < s.size() && s[p] != L'>') {
            if (iswspace(s[p])) { p++; continue; }
            if (s[p] == L'/') { selfClose = true, p++; continue; }
            size_t a = p;
            while (p < s.size() && !iswspace(s[p]) && s[p] != L'=' && s[p] != L'>' && s[p] != L'/') p++;
            std::wstring an = VizLyricsLower(s.substr(a, p - a)), av;
            while (p < s.size() && iswspace(s[p])) p++;
            if (p < s.size() && s[p] == L'=') {
                p++;
                while (p < s.size() && iswspace(s[p])) p++;
                if (p < s.size() && (s[p] == L'"' || s[p] == L'\'')) {
                    wchar_t q = s[p++];
                    size_t e = s.find(q, p);
                    av = s.substr(p, e == std::wstring::npos ? std::wstring::npos : e - p);
                    p = e == std::wstring::npos ? s.size() : e + 1;
                } else {
                    size_t a2 = p;
                    while (p < s.size() && !iswspace(s[p]) && s[p] != L'>') p++;
                    av = s.substr(a2, p - a2);
                }
            }
            if (!an.empty()) attrs.push_back({an, av});
            if (p == a) p++;
        }
        i = p < s.size() ? p + 1 : s.size();
        if (tag.empty()) continue;
        if (closing) {
            for (size_t k = stack.size(); k-- > 0;)
                if (stack[k].tag == tag) {
                    for (size_t m = stack.size(); m-- > k;)
                        if (stack[m].el >= 0) out += L"</" + stack[m].tag + L">";
                    stack.resize(k);
                    break;
                }
            continue;
        }
        const bool isVoid = in(kVoid, ARRAYSIZE(kVoid), tag);
        if (in(kDropAll, ARRAYSIZE(kDropAll), tag)) {
            if (tag == L"script") *hadScript = true;
            (*dropped)++;
            if (!isVoid && !selfClose) {
                size_t e = low.find(L"</" + tag, i);
                if (e == std::wstring::npos) i = s.size();
                else {
                    size_t g = s.find(L'>', e);
                    i = g == std::wstring::npos ? s.size() : g + 1;
                }
            }
            continue;
        }
        if (!in(kKeep, ARRAYSIZE(kKeep), tag)) {  // (anything else: its tag out, what's inside kept)
            (*dropped)++;
            if (!isVoid && !selfClose) stack.push_back({tag, -1});
            continue;
        }
        LeTplEl el;
        el.tag = tag;
        el.parent = topEl();
        std::wstring kept;
        for (auto& [an, av] : attrs) {
            std::wstring lv = VizLyricsLower(av);
            if (lv.find(L"javascript:") != std::wstring::npos || lv.find(L"url(") != std::wstring::npos || lv.find(L"expression(") != std::wstring::npos ||
                lv.find(L"@import") != std::wstring::npos || lv.find(L"behavior") != std::wstring::npos || lv.find(L'<') != std::wstring::npos) {
                (*dropped)++;
                continue;
            }
            const bool ok = an == L"class" || an == L"id" || an == L"role" || an == L"lang" || an == L"dir" || an == L"title" || an == L"style" ||
                            an.rfind(L"data-", 0) == 0 || an.rfind(L"aria-", 0) == 0;
            if (!ok) {
                if (an.rfind(L"on", 0) == 0) *hadScript = true;
                (*dropped)++;
                continue;
            }
            std::wstring v;
            for (wchar_t c : av) v += c == L'"' ? std::wstring(L"&quot;") : std::wstring(1, c);
            kept += L" " + an + L"=\"" + v + L"\"";
            if (an == L"class") el.cls = av;
            else if (an == L"id") el.id = av;
            else if (an == L"style") el.style = av;
            else if (an.rfind(L"data-", 0) == 0) el.data.push_back({an, av});
        }
        out += L"<" + tag + kept + L">";
        int idx = (int)els->size();
        if (el.parent >= 0) (*els)[el.parent].kids.push_back(idx);
        els->push_back(el);
        if (!isVoid && !selfClose) stack.push_back({tag, idx});
    }
    for (size_t m = stack.size(); m-- > 0;)
        if (stack[m].el >= 0) out += L"</" + stack[m].tag + L">";
    // (each element's place: child indexes from the template's top, as the page walks it)
    int roots = 0;
    for (size_t k = 0; k < els->size(); k++) {
        LeTplEl& e = (*els)[k];
        if (e.parent < 0) e.path = std::to_wstring(roots++);
        else {
            const auto& sib = (*els)[e.parent].kids;
            e.path = (*els)[e.parent].path + L"/" + std::to_wstring(std::find(sib.begin(), sib.end(), (int)k) - sib.begin());
        }
    }
    return out;
}


// A pen's CSS for its template: every rule under the template's own box (.ttpl), so it styles only that; the page's
// html, body and :root rules become the box's, keeping only what styles text (no background, size or layout of the page).
std::wstring VizLyrWebScopeCss(const std::wstring& in) {
    std::wstring css;
    for (size_t at = 0; at < in.size();) {  // (comments out)
        size_t c = in.find(L"/*", at);
        if (c == std::wstring::npos) { css += in.substr(at); break; }
        css += in.substr(at, c - at);
        size_t e = in.find(L"*/", c + 2);
        at = e == std::wstring::npos ? in.size() : e + 2;
    }
    std::function<std::wstring(const std::wstring&)> scope = [&](const std::wstring& s) {
        std::wstring out;
        size_t at = 0;
        while (at < s.size()) {
            size_t open = s.find(L'{', at);
            if (open == std::wstring::npos) break;
            int depth = 1;
            size_t close = open + 1;
            for (; close < s.size() && depth; close++) depth += s[close] == L'{' ? 1 : s[close] == L'}' ? -1 : 0;
            std::wstring head = s.substr(at, open - at), body = s.substr(open + 1, close - open - 2);
            if (size_t semi = head.rfind(L';'); semi != std::wstring::npos) head = head.substr(semi + 1);
            while (!head.empty() && iswspace(head.front())) head.erase(head.begin());
            while (!head.empty() && iswspace(head.back())) head.pop_back();
            std::wstring lh = VizLyricsLower(head);
            at = close;
            if (lh.rfind(L"@", 0) == 0) {
                if (lh.rfind(L"@media", 0) == 0 || lh.rfind(L"@supports", 0) == 0 || lh.rfind(L"@container", 0) == 0 || lh.rfind(L"@layer", 0) == 0)
                    out += head + L"{" + scope(body) + L"}\n";
                else if (lh.find(L"keyframes") != std::wstring::npos || lh.rfind(L"@property", 0) == 0) out += head + L"{" + body + L"}\n";
                continue;  // (@font-face and the rest: nothing to fetch, nothing kept)
            }
            std::wstring sel;
            bool allRoot = true;
            for (size_t q = 0; q <= head.size();) {
                size_t comma = head.find(L',', q);
                std::wstring one = head.substr(q, comma == std::wstring::npos ? std::wstring::npos : comma - q);
                while (!one.empty() && iswspace(one.front())) one.erase(one.begin());
                while (!one.empty() && iswspace(one.back())) one.pop_back();
                std::wstring lo = VizLyricsLower(one);
                bool root = false;
                for (const wchar_t* r : {L":root", L"html", L"body"}) {
                    size_t n = wcslen(r);
                    if (lo.compare(0, n, r) == 0 && (lo.size() == n || !(iswalnum(lo[n]) || lo[n] == L'-' || lo[n] == L'_'))) {
                        one = L".ttpl" + one.substr(n), lo = VizLyricsLower(one), root = true;
                        for (const wchar_t* r2 : {L" body", L" html", L">body", L"> body"})  // (html body ...)
                            if (size_t k = lo.find(r2); k != std::wstring::npos) one.erase(k, wcslen(r2)), lo = VizLyricsLower(one);
                        break;
                    }
                }
                if (!root) allRoot = false;
                if (!one.empty()) sel += (sel.empty() ? L"" : L",") + (root ? one : L".ttpl " + one);
                if (comma == std::wstring::npos) break;
                q = comma + 1;
            }
            if (sel.empty()) continue;
            if (allRoot) {  // (only what styles text, and custom properties)
                std::wstring kept;
                for (size_t d = 0; d < body.size();) {
                    size_t semi = body.find(L';', d);
                    std::wstring decl = body.substr(d, semi == std::wstring::npos ? std::wstring::npos : semi - d);
                    d = semi == std::wstring::npos ? body.size() : semi + 1;
                    size_t st = decl.find_first_not_of(L" \t\n");
                    if (st == std::wstring::npos) continue;
                    decl = decl.substr(st);
                    std::wstring l = VizLyricsLower(decl);
                    if (l.rfind(L"--", 0) == 0 || l.rfind(L"color", 0) == 0 || l.rfind(L"font", 0) == 0 || l.rfind(L"letter-spacing", 0) == 0 ||
                        l.rfind(L"word-spacing", 0) == 0 || l.rfind(L"text-", 0) == 0 || l.rfind(L"line-height", 0) == 0 || l.rfind(L"perspective", 0) == 0)
                        kept += decl + L";";
                }
                body = kept;
            }
            out += sel + L"{" + body + L"}\n";
        }
        return out;
    };
    return scope(css);
}

void VizJsonString(std::wstring* out, const std::wstring& s);
// ---- Scripts in your own lyric animations (Tourne Desktop only, off unless Allow Scripts in My Own Animations is on) --
// A pen's script ("#$ " lines) and the libraries it loads ("lib.N = <sha-256> <address>", each fetched once into the
// animations folder's libs\ as <sha-256>.js and checked against it on every load: a changed file is refused). They run
// only in the lyrics' own web view, locked: a fresh private profile each run, every request refused, all of its
// network sent to a proxy that isn't there (so nothing, WebRTC and name lookups included, gets out), no new windows or
// other pages, every permission and download refused, no host objects; the page hands the script the lyric line, its
// words and timing (window.ttLyric) and nothing else. Never shared: Share Mine and the gallery refuse them.
std::string VizSha256(const std::string& data) {
    static const uint32_t K[64] = {
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
        0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
        0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
        0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
        0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
        0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2};
    uint32_t h[8] = {0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19};
    std::string m = data;
    const uint64_t bits = (uint64_t)data.size() * 8;
    m += (char)0x80;
    while (m.size() % 64 != 56) m += (char)0;
    for (int i = 7; i >= 0; i--) m += (char)((bits >> (i * 8)) & 255);
    auto rotr = [](uint32_t x, int n) { return (x >> n) | (x << (32 - n)); };
    for (size_t off = 0; off < m.size(); off += 64) {
        uint32_t w[64];
        for (int i = 0; i < 16; i++)
            w[i] = (uint32_t)(uint8_t)m[off + i * 4] << 24 | (uint32_t)(uint8_t)m[off + i * 4 + 1] << 16 | (uint32_t)(uint8_t)m[off + i * 4 + 2] << 8 |
                   (uint32_t)(uint8_t)m[off + i * 4 + 3];
        for (int i = 16; i < 64; i++) {
            uint32_t s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >> 3), s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16] + s0 + w[i - 7] + s1;
        }
        uint32_t a = h[0], b = h[1], c = h[2], d = h[3], e = h[4], f = h[5], g = h[6], hh = h[7];
        for (int i = 0; i < 64; i++) {
            uint32_t t1 = hh + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i];
            uint32_t t2 = (rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & b) ^ (a & c) ^ (b & c));
            hh = g, g = f, f = e, e = d + t1, d = c, c = b, b = a, a = t1 + t2;
        }
        h[0] += a, h[1] += b, h[2] += c, h[3] += d, h[4] += e, h[5] += f, h[6] += g, h[7] += hh;
    }
    char out[65];
    for (int i = 0; i < 8; i++) sprintf_s(out + i * 8, 9, "%08x", h[i]);
    return std::string(out, 64);
}

std::wstring VizLyrLibDir() {
    WCHAR docs[MAX_PATH] = {};
    if (FAILED(SHGetFolderPathW(nullptr, CSIDL_PERSONAL, nullptr, 0, docs))) return L"";
    return std::wstring(docs) + L"\\Tourne'Table lyrics animations\\libs";
}

// The scripts to hand the page, as JSON ({"libs":[...],"pen":"..."}), each library read and checked; "" when there are
// none or one is missing or changed (`why` says which).
std::wstring VizLyrWebScripts(const std::wstring& script, const std::vector<std::pair<std::wstring, std::wstring>>& libs, std::wstring* why) {
    static std::wstring s_key, s_json, s_why;
    std::wstring key = script;
    for (auto& [sha, url] : libs) key += L"|" + sha;
    if (key == s_key) return *why = s_why, s_json;
    s_key = key, s_why.clear();
    std::wstring j = L"{\"libs\":[";
    int n = 0;
    for (auto& [sha, url] : libs) {
        std::string data;
        const std::wstring path = VizLyrLibDir() + L"\\" + sha + L".js";
        HANDLE f = CreateFileW(path.c_str(), GENERIC_READ, FILE_SHARE_READ, nullptr, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr);
        if (f != INVALID_HANDLE_VALUE) {
            LARGE_INTEGER sz{};
            if (GetFileSizeEx(f, &sz) && sz.QuadPart <= 4 * 1024 * 1024) {
                data.resize((size_t)sz.QuadPart);
                DWORD got = 0;
                if (!data.empty() && (!ReadFile(f, data.data(), (DWORD)data.size(), &got, nullptr) || got != data.size())) data.clear();
            }
            CloseHandle(f);
        }
        std::wstring wsha(sha);
        std::string got = VizSha256(data);
        if (data.empty() || std::wstring(got.begin(), got.end()) != wsha) {
            s_why = L"a library (" + url + L") is missing or changed since it was fetched, so this animation's scripts are refused";
            s_json.clear();
            return *why = s_why, s_json;
        }
        int wn = MultiByteToWideChar(CP_UTF8, 0, data.data(), (int)data.size(), nullptr, 0);
        std::wstring w(wn, L'\0');
        MultiByteToWideChar(CP_UTF8, 0, data.data(), (int)data.size(), w.data(), wn);
        j += n++ ? L"," : L"";
        VizJsonString(&j, w);
    }
    j += L"],\"pen\":";
    VizJsonString(&j, script);
    j += L"}";
    s_json = script.empty() && libs.empty() ? L"" : j;
    return *why = s_why, s_json;
}

void VizJsonString(std::wstring* out, const std::wstring& s) {
    *out += L'"';
    for (wchar_t c : s) {
        if (c == L'"' || c == L'\\') *out += L'\\', *out += c;
        else if (c == L'\n') *out += L"\\n";
        else if (c == L'\r') *out += L"\\r";
        else if (c == L'\t') *out += L"\\t";
        else if (c < 0x20 || c == 0x2028 || c == 0x2029 || c == L'<' || c == L'>') {
            wchar_t b[8];
            swprintf_s(b, L"\\u%04x", (unsigned)c);
            *out += b;
        } else *out += c;
    }
    *out += L'"';
}

std::wstring VizCssColour(uint32_t argb) {
    wchar_t b[64];
    swprintf_s(b, L"rgba(%u,%u,%u,%.3f)", (argb >> 16) & 255, (argb >> 8) & 255, argb & 255, ((argb >> 24) & 255) / 255.0);
    return b;
}

